void GlobalMapServer::UpdateOptimizedSparseMap()
{
    global_sparse_points_optimized_.clear();

    if (!multi_system_)
        return;

    auto atlas =
        multi_system_->GetAtlas();

    if (!atlas)
        return;

    const std::vector<orbslam3_multi::ImportedMapPoint> mps =
        atlas->GetAllMapPoints();

    const std::vector<orbslam3_multi::ImportedKeyFrame> keyframes =
        atlas->GetAllKeyFrames();

    const std::vector<orbslam3_multi::RawPoint> anchored_cloud =
        multi_system_->GetAnchoredCloud();

    std::unordered_map<uint64_t, orbslam3_multi::RawPoint> fallback_by_mp_id;
    fallback_by_mp_id.reserve(anchored_cloud.size());

    for (const auto& p : anchored_cloud)
    {
        fallback_by_mp_id[p.global_mappoint_id] =
            p;
    }

    // ============================================================
    // Cache de KeyFrames optimizados por submapa.
    //
    // Para cada KF optimizado guardamos:
    // - id global
    // - submapa
    // - pose local original
    // - pose world optimizada
    // - posición local
    //
    // Esto nos permite buscar un KF optimizado cercano cuando el MapPoint
    // no tiene reference/observation optimizada.
    // ============================================================

    struct OptimizedKfCache
    {
        uint64_t global_kf_id = 0;
        uint32_t drone_id = 0;
        uint64_t map_epoch = 0;

        Eigen::Vector3d local_position =
            Eigen::Vector3d::Zero();

        Eigen::Matrix4d local_T_kf =
            Eigen::Matrix4d::Identity();

        Eigen::Matrix4d world_T_kf_optimized =
            Eigen::Matrix4d::Identity();

        bool valid = false;
    };

    std::unordered_map<uint64_t, OptimizedKfCache> optimized_kf_cache_by_id;
    std::unordered_map<uint64_t, std::vector<OptimizedKfCache>> optimized_kfs_by_submap;

    optimized_kf_cache_by_id.reserve(optimized_kf_poses_.size());

    for (const auto& kf : keyframes)
    {
        if (kf.global_id == 0 ||
            kf.is_bad)
        {
            continue;
        }

        auto opt_it =
            optimized_kf_poses_.find(kf.global_id);

        if (opt_it == optimized_kf_poses_.end())
            continue;

        OptimizedKfCache cache;

        cache.global_kf_id =
            kf.global_id;

        cache.drone_id =
            kf.drone_id;

        cache.map_epoch =
            kf.map_epoch;

        cache.local_position =
            kf.position;

        cache.local_T_kf =
            KeyFrameLocalPoseToMatrix(kf);

        cache.world_T_kf_optimized =
            opt_it->second;

        cache.valid =
            true;

        optimized_kf_cache_by_id[kf.global_id] =
            cache;

        const uint64_t submap_key =
            MakeSubmapKey(
                kf.drone_id,
                kf.map_epoch);

        optimized_kfs_by_submap[submap_key].push_back(cache);
    }

    auto TransformPointUsingOptimizedKeyFrame =
        [this](
            const orbslam3_multi::ImportedMapPoint& mp,
            const OptimizedKfCache& kf_cache,
            Eigen::Vector3d& p_world_out) -> bool
        {
            if (!kf_cache.valid)
                return false;

            Eigen::Vector4d p_local;
            p_local << mp.position.x(), mp.position.y(), mp.position.z(), 1.0;

            const Eigen::Matrix4d kf_T_local =
                kf_cache.local_T_kf.inverse();

            const Eigen::Vector4d p_kf =
                kf_T_local * p_local;

            const Eigen::Vector4d p_world =
                kf_cache.world_T_kf_optimized * p_kf;

            if (!std::isfinite(p_world.x()) ||
                !std::isfinite(p_world.y()) ||
                !std::isfinite(p_world.z()))
            {
                return false;
            }

            p_world_out =
                Eigen::Vector3d(
                    p_world.x(),
                    p_world.y(),
                    p_world.z());

            return true;
        };

    auto FindNearestOptimizedKeyFrameInSameSubmap =
        [this, &optimized_kfs_by_submap](
            const orbslam3_multi::ImportedMapPoint& mp,
            OptimizedKfCache& nearest_out,
            double& best_distance_out) -> bool
        {
            best_distance_out =
                std::numeric_limits<double>::max();

            const uint64_t submap_key =
                MakeSubmapKey(
                    mp.drone_id,
                    mp.map_epoch);

            auto it =
                optimized_kfs_by_submap.find(submap_key);

            if (it == optimized_kfs_by_submap.end())
                return false;

            if (it->second.empty())
                return false;

            for (const auto& kf_cache : it->second)
            {
                if (!kf_cache.valid)
                    continue;

                const double distance =
                    (mp.position - kf_cache.local_position).norm();

                if (distance < best_distance_out)
                {
                    best_distance_out =
                        distance;

                    nearest_out =
                        kf_cache;
                }
            }

            if (!nearest_out.valid)
                return false;

            if (best_distance_out >
                optimized_cloud_nearest_kf_max_distance_m_)
            {
                return false;
            }

            return true;
        };

    size_t optimized_ref_points = 0;
    size_t optimized_obs_points = 0;
    size_t optimized_nearest_points = 0;
    size_t optimized_submap_rigid_points = 0;
    size_t fallback_raw_points = 0;

    size_t skipped_bad_points = 0;
    size_t skipped_no_reference = 0;
    size_t skipped_not_anchored = 0;
    size_t skipped_no_submap_optimized_kfs = 0;
    size_t skipped_nearest_too_far = 0;

    size_t candidate_ref_count = 0;
    size_t candidate_obs_count = 0;
    size_t candidate_ref_or_obs_not_optimized = 0;

    for (const auto& mp : mps)
    {
        if (mp.global_id == 0 ||
            mp.is_bad)
        {
            skipped_bad_points++;
            continue;
        }

        GlobalSparsePoint gp;
        gp.drone_id =
            mp.drone_id;

        gp.global_mappoint_id =
            mp.global_id;

        // Punto world temporal reutilizado por:
        // 1) reference KF
        // 2) nearest KF
        // 3) media de observaciones optimizadas
        Eigen::Vector3d p_world =
            Eigen::Vector3d::Zero();

        Eigen::Vector3d obs_sum =
            Eigen::Vector3d::Zero();

        size_t obs_used =
            0;

        // Suficiente para que el punto siga a la deformación local,
        // pero evita transformar 5, 10, 20 observaciones por MapPoint.
        constexpr size_t kMaxOptimizedObsPerPoint = 3;

        for (const auto& obs : mp.observations)
        {
            if (obs.global_keyframe_id == 0)
                continue;

            candidate_obs_count++;

            auto obs_it =
                optimized_kf_cache_by_id.find(
                    obs.global_keyframe_id);

            if (obs_it == optimized_kf_cache_by_id.end())
            {
                candidate_ref_or_obs_not_optimized++;
                continue;
            }

            Eigen::Vector3d p_world_obs =
                Eigen::Vector3d::Zero();

            if (!TransformPointUsingOptimizedKeyFrame(
                    mp,
                    obs_it->second,
                    p_world_obs))
            {
                continue;
            }

            obs_sum += p_world_obs;
            obs_used++;

            if (obs_used >= kMaxOptimizedObsPerPoint)
                break;
        }

        if (obs_used > 0)
        {
            p_world =
                obs_sum /
                static_cast<double>(obs_used);

            gp.x = p_world.x();
            gp.y = p_world.y();
            gp.z = p_world.z();

            global_sparse_points_optimized_.push_back(gp);

            optimized_obs_points++;
            continue;
        }

        // ========================================================
        // 2. Fallback por reference_keyframe_id.
        //
        // Solo se usa si el MapPoint no tenía ninguna observación
        // optimizada válida.
        // ========================================================

        if (mp.reference_keyframe_id > 0)
        {
            candidate_ref_count++;

            auto ref_it =
                optimized_kf_cache_by_id.find(
                    mp.reference_keyframe_id);

            if (ref_it != optimized_kf_cache_by_id.end())
            {
                if (TransformPointUsingOptimizedKeyFrame(
                        mp,
                        ref_it->second,
                        p_world))
                {
                    gp.x = p_world.x();
                    gp.y = p_world.y();
                    gp.z = p_world.z();

                    global_sparse_points_optimized_.push_back(gp);

                    optimized_ref_points++;
                    continue;
                }
            }
            else
            {
                candidate_ref_or_obs_not_optimized++;
            }
        }
        else
        {
            skipped_no_reference++;
        }

        // ========================================================
        // 3. Intento por KeyFrame optimizado más cercano del mismo
        // submapa.
        //
        // Esta es la parte nueva más importante de Fase 4.
        // Evita que puntos sin ref/obs optimizada caigan a raw.
        // ========================================================

        if (optimized_cloud_use_nearest_kf_fallback_)
        {
            OptimizedKfCache nearest_kf;
            double nearest_distance =
                std::numeric_limits<double>::max();

            const bool found_nearest =
                FindNearestOptimizedKeyFrameInSameSubmap(
                    mp,
                    nearest_kf,
                    nearest_distance);

            if (found_nearest)
            {
                if (TransformPointUsingOptimizedKeyFrame(
                        mp,
                        nearest_kf,
                        p_world))
                {
                    gp.x = p_world.x();
                    gp.y = p_world.y();
                    gp.z = p_world.z();

                    global_sparse_points_optimized_.push_back(gp);

                    optimized_nearest_points++;
                    continue;
                }
            }
            else
            {
                const uint64_t submap_key =
                    MakeSubmapKey(
                        mp.drone_id,
                        mp.map_epoch);

                auto submap_it =
                    optimized_kfs_by_submap.find(submap_key);

                if (submap_it == optimized_kfs_by_submap.end() ||
                    submap_it->second.empty())
                {
                    skipped_no_submap_optimized_kfs++;
                }
                else
                {
                    skipped_nearest_too_far++;
                }
            }
        }

        // ========================================================
        // 4. Transform rígido optimizado por submapa.
        //
        // Esto no corrige drift interno, pero es mejor distinguirlo
        // de fallback raw. Antes se contaba como fallback_raw.
        // ========================================================

        const uint64_t submap_key =
            MakeSubmapKey(
                mp.drone_id,
                mp.map_epoch);

        auto submap_opt_it =
            optimized_world_T_local_by_submap_.find(
                submap_key);

        if (submap_opt_it != optimized_world_T_local_by_submap_.end() &&
            submap_opt_it->second.valid)
        {
            Eigen::Vector4d p_local;
            p_local << mp.position.x(), mp.position.y(), mp.position.z(), 1.0;

            const Eigen::Vector4d p_world_rigid =
                submap_opt_it->second.world_T_local * p_local;

            if (std::isfinite(p_world_rigid.x()) &&
                std::isfinite(p_world_rigid.y()) &&
                std::isfinite(p_world_rigid.z()))
            {
                gp.x = p_world_rigid.x();
                gp.y = p_world_rigid.y();
                gp.z = p_world_rigid.z();

                global_sparse_points_optimized_.push_back(gp);

                optimized_submap_rigid_points++;
                continue;
            }
        }

        // ========================================================
        // 5. Último fallback: raw anchored cloud.
        // ========================================================

        auto fallback_it =
            fallback_by_mp_id.find(
                mp.global_id);

        if (fallback_it == fallback_by_mp_id.end())
        {
            skipped_not_anchored++;
            continue;
        }

        gp.x =
            fallback_it->second.x;

        gp.y =
            fallback_it->second.y;

        gp.z =
            fallback_it->second.z;

        global_sparse_points_optimized_.push_back(gp);

        fallback_raw_points++;
    }

    if (global_sparse_points_optimized_.size() >
        max_published_global_points_)
    {
        global_sparse_points_optimized_.resize(
            max_published_global_points_);
    }

    const size_t optimized_total =
        optimized_ref_points +
        optimized_obs_points +
        optimized_nearest_points;

    const size_t non_raw_total =
        optimized_total +
        optimized_submap_rigid_points;

    RCLCPP_INFO_THROTTLE(
        get_logger(),
        *get_clock(),
        3000,
        "[OPT10-DETAIL] points=%zu optimized_total=%zu "
        "ref=%zu obs=%zu nearest=%zu submap_rigid=%zu fallback_raw=%zu "
        "skipped_bad=%zu skipped_no_ref=%zu skipped_not_anchored=%zu "
        "skipped_no_submap_opt_kfs=%zu skipped_nearest_too_far=%zu "
        "optimized_kf_poses=%zu optimized_submaps=%zu "
        "candidate_ref=%zu candidate_obs=%zu candidate_not_optimized=%zu",
        global_sparse_points_optimized_.size(),
        optimized_total,
        optimized_ref_points,
        optimized_obs_points,
        optimized_nearest_points,
        optimized_submap_rigid_points,
        fallback_raw_points,
        skipped_bad_points,
        skipped_no_reference,
        skipped_not_anchored,
        skipped_no_submap_optimized_kfs,
        skipped_nearest_too_far,
        optimized_kf_poses_.size(),
        optimized_world_T_local_by_submap_.size(),
        candidate_ref_count,
        candidate_obs_count,
        candidate_ref_or_obs_not_optimized);

    RCLCPP_INFO_THROTTLE(
        get_logger(),
        *get_clock(),
        3000,
        "[OPT10] optimized_cloud points=%zu optimized=%zu fallback_raw=%zu "
        "non_raw=%zu optimized_kf_poses=%zu",
        global_sparse_points_optimized_.size(),
        optimized_total,
        fallback_raw_points,
        non_raw_total,
        optimized_kf_poses_.size());
}


uint64_t GlobalMapServer::MakeSubmapKey(
    uint32_t drone_id,
    uint64_t map_epoch) const
{
    return
        (static_cast<uint64_t>(drone_id) << 32) |
        (map_epoch & 0xFFFFFFFFULL);
}



bool GlobalMapServer::IsActiveDroneEpoch(
    uint32_t drone_id,
    uint64_t map_epoch) const
{
    auto it =
        drone_maps_.find(drone_id);

    if (it == drone_maps_.end())
    {
        return false;
    }

    const DroneMapData& data =
        it->second;

    if (!data.has_any_update)
    {
        return false;
    }

    return data.current_map_epoch == map_epoch;
}



uint64_t GlobalMapServer::MakeGlobalKeyFrameId(
    uint32_t drone_id,
    uint64_t map_epoch,
    uint64_t local_kf_id) const
{
    return
        (static_cast<uint64_t>(drone_id) << 48) |
        ((map_epoch & 0xFFFFULL) << 32) |
        (local_kf_id & 0xFFFFFFFFULL);
}


size_t GlobalMapServer::CountOptimizedConstrainedKfsNearFiducial(
    const ActiveFiducialWindow& window,
    const SimulatedFiducial& fiducial) const
{
    if (!multi_system_)
        return 0;

    if (!window.active)
        return 0;

    if (!window.graph_optimized_after_priors)
        return 0;

    auto atlas =
        multi_system_->GetAtlas();

    if (!atlas)
        return 0;

    const Eigen::Vector3d fid_pos(
        fiducial.world_T_fiducial.getOrigin().x(),
        fiducial.world_T_fiducial.getOrigin().y(),
        fiducial.world_T_fiducial.getOrigin().z());

    const uint64_t submap_key =
        MakeSubmapKey(
            window.drone_id,
            window.map_epoch);

    Eigen::Matrix4d optimized_world_T_local =
        Eigen::Matrix4d::Identity();

    bool has_optimized_submap_transform = false;

    auto submap_it =
        optimized_world_T_local_by_submap_.find(submap_key);

    if (submap_it != optimized_world_T_local_by_submap_.end() &&
        submap_it->second.valid &&
        submap_it->second.world_T_local.allFinite())
    {
        optimized_world_T_local =
            submap_it->second.world_T_local;

        has_optimized_submap_transform = true;
    }

    size_t count = 0;

    for (const uint64_t local_kf_id : window.constrained_local_kfs)
    {
        const uint64_t global_kf_id =
            MakeGlobalKeyFrameId(
                window.drone_id,
                window.map_epoch,
                local_kf_id);

        const orbslam3_multi::ImportedKeyFrame kf =
            atlas->GetKeyFrame(global_kf_id);

        if (kf.global_id == 0 || kf.is_bad)
            continue;

        Eigen::Matrix4d world_T_camera =
            Eigen::Matrix4d::Identity();

        bool has_optimized_pose = false;

        auto opt_it =
            optimized_kf_poses_.find(global_kf_id);

        if (opt_it != optimized_kf_poses_.end() &&
            opt_it->second.allFinite())
        {
            world_T_camera =
                opt_it->second;

            has_optimized_pose = true;
        }
        else if (has_optimized_submap_transform)
        {
            const Eigen::Matrix4d local_T_camera =
                KeyFrameLocalPoseToMatrix(kf);

            if (!local_T_camera.allFinite())
                continue;

            world_T_camera =
                optimized_world_T_local *
                local_T_camera;

            if (!world_T_camera.allFinite())
                continue;

            has_optimized_pose = true;
        }

        if (!has_optimized_pose)
            continue;

        const Eigen::Vector3d kf_pos =
            world_T_camera.block<3, 1>(0, 3);

        if (!kf_pos.allFinite())
            continue;

        const double distance =
            (kf_pos - fid_pos).norm();

        if (distance <= fiducial_lock_good_prior_max_dist_m_)
        {
            count++;
        }
    }

    return count;
}


Eigen::Matrix4d GlobalMapServer::KeyFrameLocalPoseToMatrix(
    const orbslam3_multi::ImportedKeyFrame& kf) const
{
    Eigen::Matrix4d T =
        Eigen::Matrix4d::Identity();

    Eigen::Quaterniond q =
        kf.orientation;

    q.normalize();

    T.block<3, 3>(0, 0) =
        q.toRotationMatrix();

    T.block<3, 1>(0, 3) =
        kf.position;

    return T;
}


geometry_msgs::msg::Pose GlobalMapServer::MatrixToPoseMsg(
    const Eigen::Matrix4d& T) const
{
    geometry_msgs::msg::Pose pose;

    Eigen::Matrix3d R =
        T.block<3, 3>(0, 0);

    Eigen::Quaterniond q(R);
    q.normalize();

    pose.position.x = T(0, 3);
    pose.position.y = T(1, 3);
    pose.position.z = T(2, 3);

    pose.orientation.x = q.x();
    pose.orientation.y = q.y();
    pose.orientation.z = q.z();
    pose.orientation.w = q.w();

    return pose;
}


geometry_msgs::msg::Transform GlobalMapServer::EigenMatrixToTransformMsg(
    const Eigen::Matrix4d& T) const
{
    geometry_msgs::msg::Transform msg;

    msg.translation.x = T(0, 3);
    msg.translation.y = T(1, 3);
    msg.translation.z = T(2, 3);

    Eigen::Matrix3d R =
        T.block<3, 3>(0, 0);

    Eigen::Quaterniond q(R);
    q.normalize();

    msg.rotation.x = q.x();
    msg.rotation.y = q.y();
    msg.rotation.z = q.z();
    msg.rotation.w = q.w();

    return msg;
}



double GlobalMapServer::RotationAngleDeg(
    const Eigen::Matrix3d& R) const
{
    const double trace =
        R.trace();

    double c =
        (trace - 1.0) * 0.5;

    c =
        std::max(
            -1.0,
            std::min(
                1.0,
                c));

    return
        std::acos(c) * 180.0 / M_PI;
}



double GlobalMapServer::NormalizeAngleDeg(
    double a) const
{
    while (a > 180.0)
        a -= 360.0;

    while (a < -180.0)
        a += 360.0;

    return a;
}



double GlobalMapServer::MatrixYawDeg(
    const Eigen::Matrix4d& T) const
{
    const double yaw =
        std::atan2(
            T(1, 0),
            T(0, 0));

    return yaw * 180.0 / M_PI;
}



double GlobalMapServer::MatrixRollDeg(
    const Eigen::Matrix4d& T) const
{
    const double roll =
        std::atan2(
            T(2, 1),
            T(2, 2));

    return roll * 180.0 / M_PI;
}



double GlobalMapServer::MatrixPitchDeg(
    const Eigen::Matrix4d& T) const
{
    const double pitch =
        std::atan2(
            -T(2, 0),
            std::sqrt(
                T(2, 1) * T(2, 1) +
                T(2, 2) * T(2, 2)));

    return pitch * 180.0 / M_PI;
}



void GlobalMapServer::BuildOptimizedSubmapTransformsFromPoses(
    const std::unordered_map<uint64_t, Eigen::Matrix4d>& optimized_poses,
    std::unordered_map<uint64_t, OptimizedSubmapTransform>& out) const
{
    out.clear();

    if (!multi_system_)
        return;

    auto atlas =
        multi_system_->GetAtlas();

    if (!atlas)
        return;

    for (const auto& [global_kf_id, world_T_camera_opt] : optimized_poses)
    {
        const orbslam3_multi::ImportedKeyFrame kf =
            atlas->GetKeyFrame(global_kf_id);

        if (kf.global_id == 0 || kf.is_bad)
            continue;

        const Eigen::Matrix4d local_T_camera =
            KeyFrameLocalPoseToMatrix(kf);

        if (!local_T_camera.allFinite() ||
            !world_T_camera_opt.allFinite())
        {
            continue;
        }

        const Eigen::Matrix4d world_T_local_opt =
            world_T_camera_opt *
            local_T_camera.inverse();

        if (!world_T_local_opt.allFinite())
            continue;

        const uint64_t key =
            MakeSubmapKey(
                kf.drone_id,
                kf.map_epoch);

        auto it =
            out.find(key);

        if (it == out.end() ||
            kf.stamp > it->second.stamp)
        {
            OptimizedSubmapTransform t;
            t.drone_id = kf.drone_id;
            t.map_epoch = kf.map_epoch;
            t.stamp = kf.stamp;
            t.world_T_local = world_T_local_opt;
            t.valid = true;

            out[key] = t;
        }
    }
}



bool GlobalMapServer::CheckOptimizationGuard(
    const std::unordered_map<uint64_t, OptimizedSubmapTransform>& candidate_submaps,
    double chi2_final,
    double chi2_per_edge,
    std::string& reject_reason_out,
    double& max_any_jump_out,
    double& max_fiducial_jump_out,
    double& max_fiducial_yaw_jump_out) const
{
    reject_reason_out = "ok";
    max_any_jump_out = 0.0;
    max_fiducial_jump_out = 0.0;
    max_fiducial_yaw_jump_out = 0.0;

    if (!opt_guard_enable_)
    {
        return true;
    }

    if (opt_guard_reject_on_large_chi_)
    {
        if (chi2_final > opt_guard_max_final_chi2_)
        {
            reject_reason_out = "final_chi2_too_high";
            return false;
        }

        if (chi2_per_edge > opt_guard_max_chi2_per_edge_)
        {
            reject_reason_out = "chi2_per_edge_too_high";
            return false;
        }
    }

    for (const auto& [drone_id, data] : drone_maps_)
    {
        if (!data.has_correction)
            continue;

        if (!IsFiniteTransform(data.world_T_local))
            continue;

        const uint64_t key =
            MakeSubmapKey(
                drone_id,
                data.current_map_epoch);

        auto cand_it =
            candidate_submaps.find(key);

        if (cand_it == candidate_submaps.end() ||
            !cand_it->second.valid ||
            !cand_it->second.world_T_local.allFinite())
        {
            continue;
        }

        const Eigen::Matrix4d old_T =
            Tf2ToEigenMatrix(
                TransformMsgToTf2(
                    data.world_T_local));

        const Eigen::Matrix4d new_T =
            cand_it->second.world_T_local;

        const Eigen::Vector3d old_t =
            old_T.block<3, 1>(0, 3);

        const Eigen::Vector3d new_t =
            new_T.block<3, 1>(0, 3);

        const double trans_jump =
            (new_t - old_t).norm();

        const double z_jump =
            std::abs(
                new_t.z() - old_t.z());

        const double yaw_jump =
            std::abs(
                NormalizeAngleDeg(
                    MatrixYawDeg(new_T) -
                    MatrixYawDeg(old_T)));

        max_any_jump_out =
            std::max(
                max_any_jump_out,
                trans_jump);

        if (data.has_absolute_correction)
        {
            max_fiducial_jump_out =
                std::max(
                    max_fiducial_jump_out,
                    trans_jump);

            max_fiducial_yaw_jump_out =
                std::max(
                    max_fiducial_yaw_jump_out,
                    yaw_jump);
        }

        if (opt_guard_log_details_)
        {
            RCLCPP_WARN(
                get_logger(),
                "[OPT-GUARD-SUBMAP] drone_%u epoch=%lu absolute=%s "
                "jump=%.3f z_jump=%.3f yaw_jump=%.3f "
                "old=(%.3f,%.3f,%.3f) new=(%.3f,%.3f,%.3f)",
                drone_id,
                data.current_map_epoch,
                data.has_absolute_correction ? "true" : "false",
                trans_jump,
                z_jump,
                yaw_jump,
                old_t.x(),
                old_t.y(),
                old_t.z(),
                new_t.x(),
                new_t.y(),
                new_t.z());
        }

        if (trans_jump > opt_guard_max_any_translation_jump_m_)
        {
            reject_reason_out = "any_submap_translation_jump_too_high";
            return false;
        }

        if (yaw_jump > opt_guard_max_any_yaw_jump_deg_)
        {
            reject_reason_out = "any_submap_yaw_jump_too_high";
            return false;
        }

        if (data.has_absolute_correction &&
            opt_guard_reject_on_fiducial_jump_)
        {
            if (trans_jump > opt_guard_max_fiducial_translation_jump_m_)
            {
                reject_reason_out = "fiducial_anchor_translation_jump_too_high";
                return false;
            }

            if (z_jump > opt_guard_max_fiducial_z_jump_m_)
            {
                reject_reason_out = "fiducial_anchor_z_jump_too_high";
                return false;
            }

            if (yaw_jump > opt_guard_max_fiducial_yaw_jump_deg_)
            {
                reject_reason_out = "fiducial_anchor_yaw_jump_too_high";
                return false;
            }
        }
    }

    return true;
}



void GlobalMapServer::RebuildOptimizedSubmapTransforms()
{
    optimized_world_T_local_by_submap_.clear();

    if (!multi_system_)
        return;

    auto atlas =
        multi_system_->GetAtlas();

    if (!atlas)
        return;

    for (const auto& [global_kf_id, world_T_camera_opt] : optimized_kf_poses_)
    {
        const orbslam3_multi::ImportedKeyFrame kf =
            atlas->GetKeyFrame(global_kf_id);

        if (kf.global_id == 0 || kf.is_bad)
            continue;

        const Eigen::Matrix4d local_T_camera =
            KeyFrameLocalPoseToMatrix(kf);

        if (!local_T_camera.allFinite() ||
            !world_T_camera_opt.allFinite())
        {
            continue;
        }

        const Eigen::Matrix4d world_T_local_opt =
            world_T_camera_opt *
            local_T_camera.inverse();

        if (!world_T_local_opt.allFinite())
            continue;

        const uint64_t key =
            MakeSubmapKey(
                kf.drone_id,
                kf.map_epoch);

        auto it =
            optimized_world_T_local_by_submap_.find(key);

        /*
         * Versión antigua funcional:
         *
         * Nos quedamos con el KF optimizado más reciente de ese submapa.
         * No usamos hard anchors aquí.
         *
         * Este transform solo es fallback rígido para puntos que no pueden
         * seguir la deformación por observación/reference/nearest KF.
         */
        if (it == optimized_world_T_local_by_submap_.end() ||
            kf.stamp > it->second.stamp)
        {
            OptimizedSubmapTransform t;
            t.drone_id = kf.drone_id;
            t.map_epoch = kf.map_epoch;
            t.stamp = kf.stamp;
            t.world_T_local = world_T_local_opt;
            t.valid = true;

            optimized_world_T_local_by_submap_[key] = t;
        }
    }

    RCLCPP_WARN(
        get_logger(),
        "[OPT10-SUBMAP] rebuilt optimized submap transforms: submaps=%zu optimized_kfs=%zu",
        optimized_world_T_local_by_submap_.size(),
        optimized_kf_poses_.size());
}



void GlobalMapServer::ApplyOptimizedSubmapCorrectionsToActiveDrones()
{
    for (auto& [drone_id, data] : drone_maps_)
    {
        const uint64_t key =
            MakeSubmapKey(
                drone_id,
                data.current_map_epoch);

        auto it =
            optimized_world_T_local_by_submap_.find(key);

        if (it == optimized_world_T_local_by_submap_.end() ||
            !it->second.valid)
        {
            continue;
        }

        /*
         * Fase 8B-fix:
         * Antes de aplicar una corrección optimizada al servidor,
         * comprobamos si el submapa está solo provisionalmente anclado.
         *
         * Si está PROVISIONAL, NO se debe escribir data.world_T_local.
         */
        if (multi_system_)
        {
            orbslam3_multi::MapAnchor anchor_info;

            if (multi_system_->GetMapAnchorInfo(
                    drone_id,
                    data.current_map_epoch,
                    anchor_info))
            {
                if (anchor_info.source ==
                    orbslam3_multi::AnchorSource::FIDUCIAL_DIRECT)
                {
                    RCLCPP_WARN(
                        get_logger(),
                        "[OPT10-CORR-SKIP] drone_%u epoch=%lu "
                        "reason=fiducial_direct_anchor_is_immutable "
                        "action=do_not_overwrite_world_T_local",
                        drone_id,
                        data.current_map_epoch);

                    continue;
                }

                if (anchor_info.source ==
                    orbslam3_multi::AnchorSource::LOOP_OR_PROPAGATED)
                {
                    RCLCPP_WARN(
                        get_logger(),
                        "[OPT10-CORR-SKIP] drone_%u epoch=%lu "
                        "reason=loop_anchor_world_T_local_owned_by_anchor_pipeline "
                        "maturity=%s action=do_not_overwrite_world_T_local",
                        drone_id,
                        data.current_map_epoch,
                        anchor_info.maturity ==
                            orbslam3_multi::AnchorMaturity::CONFIRMED
                                ? "CONFIRMED"
                                : anchor_info.maturity ==
                                    orbslam3_multi::AnchorMaturity::PROVISIONAL
                                        ? "PROVISIONAL"
                                        : "UNKNOWN");

                    continue;
                }
            }
        }

        geometry_msgs::msg::Transform tf_msg =
            EigenMatrixToTransformMsg(
                it->second.world_T_local);

        if (!IsFiniteTransform(tf_msg))
            continue;

        const bool was_absolute =
            data.has_absolute_correction;

        data.world_T_local =
            tf_msg;

        data.has_correction =
            true;

        data.has_absolute_correction =
            was_absolute;

        if (multi_system_)
        {
            multi_system_->SetMapAnchor(
                drone_id,
                data.current_map_epoch,
                it->second.world_T_local);
        }

        RCLCPP_WARN(
            get_logger(),
            "[OPT10-CORR] applied optimized world_T_local to active drone_%u epoch=%lu "
            "preserve_absolute=%s source=%s",
            drone_id,
            data.current_map_epoch,
            was_absolute ? "true" : "false",
            data.has_absolute_correction
                ? "FIDUCIAL_DIRECT"
                : "LOOP_OR_PROPAGATED_ANCHOR");
    }
}



bool GlobalMapServer::AnyDroneHasCorrection() const
{
    for (const auto& [drone_id, data] : drone_maps_)
    {
        (void)drone_id;

        if (data.has_correction)
            return true;
    }

    return false;
}

uint64_t GlobalMapServer::MakeFiducialWindowKey(
    uint32_t drone_id,
    uint64_t map_epoch,
    uint32_t fiducial_id) const
{
    return
        (static_cast<uint64_t>(drone_id) << 56) |
        ((map_epoch & 0x00FFFFFFULL) << 32) |
        static_cast<uint64_t>(fiducial_id);
}


uint64_t GlobalMapServer::GetMaxLocalKeyFrameId(
    const DroneMapData& data) const
{
    uint64_t max_id = 0;

    for (const auto& [local_kf_id, kf_msg] : data.keyframes)
    {
        if (kf_msg.is_bad)
            continue;

        max_id =
            std::max(
                max_id,
                local_kf_id);
    }

    return max_id;
}


void GlobalMapServer::UpdateActiveFiducialWindow(
    uint32_t drone_id,
    DroneMapData& data,
    const SimulatedFiducial& fiducial,
    double distance_to_fiducial,
    const tf2::Transform& T_world_camera,
    const tf2::Transform& T_local_camera)
{
    const uint64_t key =
        MakeFiducialWindowKey(
            drone_id,
            data.current_map_epoch,
            fiducial.id);

    auto& window =
        active_fiducial_windows_[key];

    const bool was_active =
        window.active;

    const rclcpp::Time now_time =
        now();

    if (!window.active)
    {
        window.active = true;

        window.drone_id =
            drone_id;

        window.map_epoch =
            data.current_map_epoch;

        window.fiducial_id =
            fiducial.id;

        window.enter_time =
            now_time;

        window.enter_stamp =
            now_time;

        window.max_local_kf_id_at_enter =
            GetMaxLocalKeyFrameId(data);

        window.min_distance_to_fiducial =
            distance_to_fiducial;

        window.constrained_local_kfs.clear();

        window.T_world_fiducial =
            fiducial.world_T_fiducial;

        window.fiducial_radius =
            fiducial.detection_radius_m;

        window.has_been_ready = false;

        window.first_ready_time = rclcpp::Time(0, 0, get_clock()->get_clock_type());

        RCLCPP_WARN(
            get_logger(),
            "[PIPE0-FID-WINDOW-OPEN] t=%.3f drone_%u epoch=%lu fiducial_%u "
            "dist=%.3f max_kf_at_enter=%lu local_kfs=%zu local_mps=%zu "
            "radius=%.3f",
            now().seconds(),
            drone_id,
            data.current_map_epoch,
            fiducial.id,
            distance_to_fiducial,
            window.max_local_kf_id_at_enter,
            data.keyframes.size(),
            data.mappoints.size(),
            fiducial.detection_radius_m);
    }

    // Siempre refrescamos la ventana mientras el dron siga dentro del fiducial.
    window.last_seen_time =
        now_time;

    window.last_seen_stamp =
        now_time;

    window.T_world_camera_last =
        T_world_camera;

    window.T_local_camera_last =
        T_local_camera;

    if (!window.has_best_observation ||
        distance_to_fiducial < window.min_distance_to_fiducial)
    {
        window.min_distance_to_fiducial =
            distance_to_fiducial;

        window.best_T_world_camera =
            T_world_camera;

        window.best_T_local_camera =
            T_local_camera;

        window.has_best_observation =
            true;

        RCLCPP_WARN(
            get_logger(),
            "[PIPE0-FID-WINDOW-BEST] t=%.3f drone_%u epoch=%lu fiducial_%u "
            "best_dist=%.3f world_camera=%s local_camera=%s",
            now().seconds(),
            drone_id,
            data.current_map_epoch,
            fiducial.id,
            distance_to_fiducial,
            Tf2TranslationToString(T_world_camera).c_str(),
            Tf2TranslationToString(T_local_camera).c_str());

        ApplyFastFiducialAnchorGuess(
            drone_id,
            data,
            window,
            T_world_camera,
            T_local_camera,
            distance_to_fiducial);

        RefreshExistingFiducialPriorsForWindow(
            window,
            data,
            "best_observation_refresh");


        if (ShouldApplyLocalFiducialWarp(window, "best_observation"))
        {
            ApplyLocalFiducialCacheWarp(
                drone_id,
                data,
                window,
                T_world_camera,
                T_local_camera,
                distance_to_fiducial,
                "best_observation");
        }
    }

    // Backfill solo al abrir la ventana, no en cada tick.
    // Si se ejecuta en cada tick, reintentará KFs antiguos continuamente.
    if (!was_active)
    {
        TryCreateBackfillPriorsForWindow(
            window,
            data);
        
        if (ShouldApplyLocalFiducialWarp(window, "window_tick"))
        {
            ApplyLocalFiducialCacheWarp(
                drone_id,
                data,
                window,
                T_world_camera,
                T_local_camera,
                distance_to_fiducial,
                "window_tick");
        }
    }

    const size_t constrained_before =
        window.constrained_local_kfs.size();

    TryCreateFiducialPriorsForWindow(
        window,
        data);

    const size_t constrained_after =
        window.constrained_local_kfs.size();

    RCLCPP_INFO_THROTTLE(
        get_logger(),
        *get_clock(),
        1000,
        "[PIPE0-FID-WINDOW-STATE] t=%.3f drone_%u epoch=%lu fiducial_%u "
        "active=%s dist=%.3f min_dist=%.3f local_kfs=%zu "
        "constrained_before=%zu constrained_after=%zu total_priors=%zu good_priors=%zu "
        "initial_anchor=%s graph_optimized_after_priors=%s low_chi=%s constrained=%zu",
        now().seconds(),
        drone_id,
        data.current_map_epoch,
        fiducial.id,
        window.active ? "true" : "false",
        distance_to_fiducial,
        window.min_distance_to_fiducial,
        data.keyframes.size(),
        constrained_before,
        constrained_after,
        window.total_prior_count,
        window.good_prior_count,
        window.initial_anchor_created ? "true" : "false",
        window.graph_optimized_after_priors ? "true" : "false",
        window.last_optimization_low_chi ? "true" : "false",
        window.constrained_local_kfs.size());

    if (constrained_after > 0)
    {
        if (ShouldApplyLocalFiducialWarp(window, constrained_after > constrained_before ? "after_new_priors" : "after_window_update"))
        {
            ApplyLocalFiducialCacheWarp(
                drone_id,
                data,
                window,
                T_world_camera,
                T_local_camera,
                distance_to_fiducial,
                constrained_after > constrained_before
                ? "after_new_priors"
                : "after_window_update");
        }
    }
}


bool GlobalMapServer::HasSeenDifferentFiducialInEpoch(
    uint32_t drone_id,
    uint64_t map_epoch,
    uint32_t fiducial_id) const
{
    auto drone_it =
        last_fiducial_correction_time_.find(drone_id);

    if (drone_it == last_fiducial_correction_time_.end())
        return false;

    const auto& by_fiducial =
        drone_it->second;

    for (const auto& [fid_epoch_key, stamp] : by_fiducial)
    {
        (void)stamp;

        const uint64_t stored_epoch =
            fid_epoch_key >> 32;

        const uint32_t stored_fiducial_id =
            static_cast<uint32_t>(
                fid_epoch_key & 0xFFFFFFFFULL);

        if (stored_epoch != map_epoch)
            continue;

        if (stored_fiducial_id != fiducial_id)
            return true;
    }

    return false;
}



bool GlobalMapServer::ApplyFastFiducialAnchorGuess(
    uint32_t drone_id,
    DroneMapData& data,
    const ActiveFiducialWindow& window,
    const tf2::Transform& T_world_camera,
    const tf2::Transform& T_local_camera,
    double distance_to_fiducial)
{
    if (!enable_fast_fiducial_anchor_guess_)
        return false;

    if (!multi_system_)
        return false;

    if (!data.has_correction)
        return false;

    if (distance_to_fiducial > window.fiducial_radius)
        return false;

    if (fast_anchor_only_if_no_other_fiducial_in_epoch_ &&
        HasSeenDifferentFiducialInEpoch(
            drone_id,
            data.current_map_epoch,
            window.fiducial_id))
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-FAST-ANCHOR-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=different_fiducial_already_seen_in_epoch. "
            "Using pose-graph priors instead of rigid anchor.",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id);

        return false;
    }

    const tf2::Transform T_world_local_current =
        TransformMsgToTf2(
            data.world_T_local);

    const tf2::Transform T_world_local_from_fiducial =
        T_world_camera *
        T_local_camera.inverse();

    const tf2::Vector3 current_t =
        T_world_local_current.getOrigin();

    const tf2::Vector3 target_t =
        T_world_local_from_fiducial.getOrigin();

    const double delta_anchor =
        (target_t - current_t).length();

    if (delta_anchor < fast_fiducial_anchor_min_improvement_m_)
        return false;

    const tf2::Transform T_world_local_guess =
        InterpolateTf2Transform(
            T_world_local_current,
            T_world_local_from_fiducial,
            fast_fiducial_anchor_blend_);

    const tf2::Transform T_delta_world =
        T_world_local_guess *
        T_world_local_current.inverse();

    geometry_msgs::msg::Transform tf_msg =
        Tf2ToTransformMsg(
            T_world_local_guess);

    if (!IsFiniteTransform(tf_msg))
        return false;

    data.world_T_local =
        tf_msg;

    data.has_correction =
        true;

    data.has_absolute_correction =
        true;

    const Eigen::Matrix4d T_eigen =
        Tf2ToEigenMatrix(
            T_world_local_guess);

    multi_system_->SetMapAnchor(
        drone_id,
        data.current_map_epoch,
        T_eigen);

    const Eigen::Matrix4d T_delta_eigen =
        Tf2ToEigenMatrix(
            T_delta_world);

    ApplyFastAnchorDeltaToOptimizedCaches(
        drone_id,
        data.current_map_epoch,
        T_delta_eigen);

    force_pose_graph_optimization_ =
        true;

    map_dirty_ =
        true;

    keyframes_dirty_ =
        true;

    RCLCPP_WARN(
        get_logger(),
        "[FID-FAST-ANCHOR] drone_%u epoch=%lu fiducial_%u "
        "dist_fid=%.3f delta_anchor=%.3f blend=%.3f "
        "current=%s target=%s applied=%s",
        drone_id,
        data.current_map_epoch,
        window.fiducial_id,
        distance_to_fiducial,
        delta_anchor,
        fast_fiducial_anchor_blend_,
        Tf2TranslationToString(T_world_local_current).c_str(),
        Tf2TranslationToString(T_world_local_from_fiducial).c_str(),
        Tf2TranslationToString(T_world_local_guess).c_str());

    return true;
}


bool GlobalMapServer::ApplyLocalFiducialCacheWarp(
    uint32_t drone_id,
    DroneMapData& data,
    ActiveFiducialWindow& window,
    const tf2::Transform& T_world_camera,
    const tf2::Transform& T_local_camera,
    double distance_to_fiducial,
    const std::string& reason)
{
    if (!enable_local_fiducial_cache_warp_)
    {
        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            2000,
            "[FID-LOCAL-WARP-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=%s disabled",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id,
            reason.c_str());

        return false;
    }

    if (!multi_system_)
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-LOCAL-WARP-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=%s no_multi_system",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id,
            reason.c_str());

        return false;
    }

    if (!data.has_correction)
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-LOCAL-WARP-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=%s no_map_correction",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id,
            reason.c_str());

        return false;
    }

    if (distance_to_fiducial > window.fiducial_radius)
    {
        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            2000,
            "[FID-LOCAL-WARP-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=%s outside_fiducial dist=%.3f radius=%.3f",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id,
            reason.c_str(),
            distance_to_fiducial,
            window.fiducial_radius);

        return false;
    }

    // Esta corrección local solo tiene sentido para segundos fiduciales
    // o posteriores. Para el primer fiducial ya existe el anchor normal.
    if (!HasSeenDifferentFiducialInEpoch(
            drone_id,
            data.current_map_epoch,
            window.fiducial_id))
    {
        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            2000,
            "[FID-LOCAL-WARP-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=%s no_previous_different_fiducial",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id,
            reason.c_str());

        return false;
    }

    if (window.constrained_local_kfs.empty())
    {
        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            2000,
            "[FID-LOCAL-WARP-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=%s no_constrained_kfs",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id,
            reason.c_str());

        return false;
    }

    uint64_t min_local_id =
        std::numeric_limits<uint64_t>::max();

    uint64_t max_local_id =
        0;

    for (uint64_t local_id : window.constrained_local_kfs)
    {
        min_local_id =
            std::min(
                min_local_id,
                local_id);

        max_local_id =
            std::max(
                max_local_id,
                local_id);
    }

    if (min_local_id == std::numeric_limits<uint64_t>::max())
        return false;

    const uint64_t margin =
        static_cast<uint64_t>(
            std::max(
                0,
                local_fiducial_cache_warp_margin_kfs_));

    const uint64_t min_allowed =
        min_local_id > margin
            ? min_local_id - margin
            : 0;

    const uint64_t max_allowed =
        max_local_id + margin;

    const tf2::Transform T_world_local_from_fiducial =
        T_world_camera *
        T_local_camera.inverse();

    const Eigen::Matrix4d T_world_local_target =
        Tf2ToEigenMatrix(
            T_world_local_from_fiducial);

    const Eigen::Matrix4d T_world_local_current =
        Tf2ToEigenMatrix(
            TransformMsgToTf2(
                data.world_T_local));

    size_t moved = 0;
    size_t inserted = 0;
    size_t skipped_range = 0;
    size_t skipped_far = 0;
    size_t skipped_bad_pose = 0;

    for (const auto& [local_kf_id, kf_msg] : data.keyframes)
    {
        if (kf_msg.is_bad)
            continue;

        if (local_kf_id < min_allowed ||
            local_kf_id > max_allowed)
        {
            skipped_range++;
            continue;
        }

        tf2::Transform T_local_kf_tf;

        if (!GetLocalKeyFramePose(
                data,
                local_kf_id,
                T_local_kf_tf))
        {
            skipped_bad_pose++;
            continue;
        }

        const Eigen::Matrix4d T_local_kf =
            Tf2ToEigenMatrix(
                T_local_kf_tf);

        Eigen::Matrix4d T_target =
            T_world_local_target *
            T_local_kf;

        if (!T_target.allFinite())
        {
            skipped_bad_pose++;
            continue;
        }

        const Eigen::Vector3d target_pos =
            T_target.block<3, 1>(0, 3);

        const Eigen::Vector3d fid_pos(
            window.T_world_fiducial.getOrigin().x(),
            window.T_world_fiducial.getOrigin().y(),
            window.T_world_fiducial.getOrigin().z());

        const double dist_to_fid =
            (target_pos - fid_pos).norm();

        if (dist_to_fid >
            local_fiducial_cache_warp_max_distance_m_)
        {
            skipped_far++;
            continue;
        }

        const uint64_t global_kf_id =
            MakeGlobalId(
                drone_id,
                data.current_map_epoch,
                local_kf_id);

        Eigen::Matrix4d T_current =
            Eigen::Matrix4d::Identity();

        auto opt_it =
            optimized_kf_poses_.find(
                global_kf_id);

        if (opt_it != optimized_kf_poses_.end())
        {
            T_current =
                opt_it->second;
        }
        else
        {
            T_current =
                T_world_local_current *
                T_local_kf;

            inserted++;
        }

        if (!T_current.allFinite())
        {
            skipped_bad_pose++;
            continue;
        }

        tf2::Transform T_current_tf;
        tf2::Transform T_target_tf;

        EigenMatrixToTf2(
            T_current,
            T_current_tf);

        EigenMatrixToTf2(
            T_target,
            T_target_tf);

        const tf2::Transform T_blended_tf =
            InterpolateTf2Transform(
                T_current_tf,
                T_target_tf,
                local_fiducial_cache_warp_blend_);

        const Eigen::Matrix4d T_blended =
            Tf2ToEigenMatrix(
                T_blended_tf);

        if (!T_blended.allFinite())
        {
            skipped_bad_pose++;
            continue;
        }

        optimized_kf_poses_[global_kf_id] =
            T_blended;

        moved++;
    }

    if (moved == 0)
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-LOCAL-WARP-SKIP] drone_%u epoch=%lu fiducial_%u "
            "reason=%s no_kfs_moved range=[%lu,%lu] constrained=%zu "
            "skipped_range=%zu skipped_far=%zu skipped_bad_pose=%zu",
            drone_id,
            data.current_map_epoch,
            window.fiducial_id,
            reason.c_str(),
            min_allowed,
            max_allowed,
            window.constrained_local_kfs.size(),
            skipped_range,
            skipped_far,
            skipped_bad_pose);

        return false;
    }

    window.local_warp_applied = true;
    window.local_warp_moved_kfs += moved;

    global_sparse_points_optimized_.clear();

    map_dirty_ =
        true;

    keyframes_dirty_ =
        true;

    force_pose_graph_optimization_ =
        true;

    RCLCPP_WARN(
        get_logger(),
        "[FID-LOCAL-WARP] drone_%u epoch=%lu fiducial_%u "
        "reason=%s dist_fid=%.3f blend=%.3f range=[%lu,%lu] "
        "constrained=%zu moved=%zu inserted=%zu skipped_range=%zu "
        "skipped_far=%zu skipped_bad_pose=%zu",
        drone_id,
        data.current_map_epoch,
        window.fiducial_id,
        reason.c_str(),
        distance_to_fiducial,
        local_fiducial_cache_warp_blend_,
        min_allowed,
        max_allowed,
        window.constrained_local_kfs.size(),
        moved,
        inserted,
        skipped_range,
        skipped_far,
        skipped_bad_pose);

    return true;
}


void GlobalMapServer::ApplyFastAnchorDeltaToOptimizedCaches(
    uint32_t drone_id,
    uint64_t map_epoch,
    const Eigen::Matrix4d& delta_world_T_world)
{
    if (!delta_world_T_world.allFinite())
        return;

    size_t moved_kfs = 0;

    for (const auto& [global_kf_id, kf_lite] : global_keyframes_by_id_)
    {
        if (kf_lite.drone_id != drone_id)
            continue;

        if (kf_lite.map_epoch != map_epoch)
            continue;

        auto opt_it =
            optimized_kf_poses_.find(global_kf_id);

        if (opt_it == optimized_kf_poses_.end())
            continue;

        opt_it->second =
            delta_world_T_world *
            opt_it->second;

        moved_kfs++;
    }

    const uint64_t submap_key =
        MakeSubmapKey(
            drone_id,
            map_epoch);

    auto submap_it =
        optimized_world_T_local_by_submap_.find(
            submap_key);

    if (submap_it != optimized_world_T_local_by_submap_.end() &&
        submap_it->second.valid)
    {
        submap_it->second.world_T_local =
            delta_world_T_world *
            submap_it->second.world_T_local;
    }

    global_sparse_points_optimized_.clear();

    map_dirty_ =
        true;

    keyframes_dirty_ =
        true;

    RCLCPP_WARN(
        get_logger(),
        "[FID-FAST-ANCHOR-CACHE] drone_%u epoch=%lu moved_optimized_kfs=%zu "
        "has_submap_cache=%s",
        drone_id,
        map_epoch,
        moved_kfs,
        submap_it != optimized_world_T_local_by_submap_.end() ? "true" : "false");
}


void GlobalMapServer::CloseExpiredFiducialWindows()
{
    const rclcpp::Time now_time =
        now();

    std::vector<uint64_t> to_close;

    for (const auto& [key, window] : active_fiducial_windows_)
    {
        if (!window.active)
            continue;

        const double dt =
            (now_time - window.last_seen_time).seconds();

        if (dt > fiducial_window_timeout_s_)
        {
            RCLCPP_WARN(
                get_logger(),
                "[FID-WINDOW-CLOSE] drone_%u epoch=%lu fiducial_%u "
                "inactive_dt=%.3f constrained_kfs=%zu min_dist=%.3f",
                window.drone_id,
                window.map_epoch,
                window.fiducial_id,
                dt,
                window.constrained_local_kfs.size(),
                window.min_distance_to_fiducial);

            to_close.push_back(key);
        }
    }

    for (uint64_t key : to_close)
    {
        active_fiducial_windows_.erase(key);
    }
}

void GlobalMapServer::TryCreateFiducialPriorsForWindow(
    ActiveFiducialWindow& window,
    DroneMapData& data)
{
    if (!window.active)
        return;

    size_t created = 0;
    size_t skipped_old = 0;
    size_t skipped_duplicate = 0;
    size_t skipped_bad = 0;

    std::vector<uint64_t> candidate_kfs;

    for (const auto& [local_kf_id, kf] : data.keyframes)
    {
        if (kf.is_bad)
        {
            skipped_bad++;
            continue;
        }

        if (local_kf_id <= window.max_local_kf_id_at_enter)
        {
            skipped_old++;
            continue;
        }

        if (window.constrained_local_kfs.count(local_kf_id) > 0)
        {
            skipped_duplicate++;
            continue;
        }

        candidate_kfs.push_back(local_kf_id);
    }

    std::sort(
        candidate_kfs.begin(),
        candidate_kfs.end());

    for (uint64_t local_kf_id : candidate_kfs)
    {
        if (created >=
            static_cast<size_t>(fiducial_window_max_new_kfs_per_tick_))
        {
            break;
        }

        const bool ok =
            TryCreateFiducialPriorForKeyFrame(
                window,
                data,
                local_kf_id,
                "window_new_kf");

        if (ok)
            created++;
    }

    RCLCPP_INFO_THROTTLE(
        get_logger(),
        *get_clock(),
        2000,
        "[FID-WINDOW-PRIORS] drone_%u epoch=%lu fiducial_%u "
        "candidates=%zu created=%zu constrained_total=%zu "
        "skipped_old=%zu skipped_duplicate=%zu skipped_bad=%zu",
        window.drone_id,
        window.map_epoch,
        window.fiducial_id,
        candidate_kfs.size(),
        created,
        window.constrained_local_kfs.size(),
        skipped_old,
        skipped_duplicate,
        skipped_bad);
}


bool GlobalMapServer::TryCreateFiducialPriorForKeyFrame(
    const ActiveFiducialWindow& window,
    DroneMapData& data,
    uint64_t local_kf_id,
    const std::string& reason,
    bool allow_update_existing)
{
    if (!window.active)
        return false;

    if (window.drone_id == 0)
        return false;

    if (window.map_epoch != data.current_map_epoch)
        return false;

    if (!allow_update_existing &&
        window.constrained_local_kfs.count(local_kf_id) > 0)
    {
        return false;
    }


    auto kf_it =
        data.keyframes.find(local_kf_id);

    if (kf_it == data.keyframes.end())
    {
        RCLCPP_WARN(
            get_logger(),
            "[PIPE0-FID-PRIOR-REJECT] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu reason=no_kf_msg source=%s",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id,
            reason.c_str());

        return false;
    }

    const auto& kf_msg =
        kf_it->second;

    if (kf_msg.is_bad)
    {
        RCLCPP_WARN(
            get_logger(),
            "[PIPE0-FID-PRIOR-REJECT] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu reason=bad_kf source=%s",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id,
            reason.c_str());

        return false;
    }

    const double kf_stamp_s =
        static_cast<double>(kf_msg.stamp.sec) +
        static_cast<double>(kf_msg.stamp.nanosec) * 1e-9;

    RCLCPP_INFO_THROTTLE(
        get_logger(),
        *get_clock(),
        2000,
        "[FID-WINDOW-KF-TIME] drone_%u epoch=%lu fiducial_%u "
        "kf=%lu kf_stamp=%.3f ros_now=%.3f source=%s "
        "note=not_filtering_by_time_different_clock_domains",
        window.drone_id,
        window.map_epoch,
        window.fiducial_id,
        local_kf_id,
        kf_stamp_s,
        now().seconds(),
        reason.c_str());

    tf2::Transform T_local_kf;

    if (!GetLocalKeyFramePose(
            data,
            local_kf_id,
            T_local_kf))
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-WINDOW-PRIOR-REJECT] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu reason=no_local_kf_pose",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id);

        return false;
    }

    const tf2::Transform T_world_camera_for_prior =
        window.has_best_observation
            ? window.best_T_world_camera
            : window.T_world_camera_last;

    const tf2::Transform T_local_camera_for_prior =
        window.has_best_observation
            ? window.best_T_local_camera
            : window.T_local_camera_last;

    const tf2::Transform T_world_local_measured =
        T_world_camera_for_prior *
        T_local_camera_for_prior.inverse();

    const tf2::Transform T_world_kf_measured =
        T_world_local_measured *
        T_local_kf;

    const tf2::Vector3 kf_world_pos =
        T_world_kf_measured.getOrigin();

    const tf2::Vector3 fid_world_pos =
        window.T_world_fiducial.getOrigin();

    const double dx_fid =
        kf_world_pos.x() - fid_world_pos.x();

    const double dy_fid =
        kf_world_pos.y() - fid_world_pos.y();

    const double dz_fid =
        kf_world_pos.z() - fid_world_pos.z();

    const double dxy_fid =
        std::sqrt(dx_fid * dx_fid + dy_fid * dy_fid);

    const double d3_fid =
        std::sqrt(dx_fid * dx_fid + dy_fid * dy_fid + dz_fid * dz_fid);

    const uint64_t global_kf_id =
        MakeGlobalId(
            window.drone_id,
            window.map_epoch,
            local_kf_id);

    if (!allow_update_existing &&
        window.constrained_local_kfs.size() >=
            fiducial_window_max_constraints_per_window_ &&
        d3_fid > fiducial_prior_strong_distance_m_)
    {
        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            2000,
            "[FID-WINDOW-PRIOR-REJECT] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu reason=window_constraint_limit dist_to_fid=%.3f "
            "strong_distance=%.3f reached=%zu max=%zu source=%s",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id,
            d3_fid,
            fiducial_prior_strong_distance_m_,
            window.constrained_local_kfs.size(),
            fiducial_window_max_constraints_per_window_,
            reason.c_str());

        return false;
    }

    if (reject_far_fiducial_priors_ &&
        d3_fid > fiducial_prior_reject_distance_m_)
    {
        bool removed_existing = false;

        if (multi_system_)
        {
            removed_existing =
                multi_system_->RemoveFiducialPoseConstraint(
                    window.drone_id,
                    window.map_epoch,
                    global_kf_id,
                    window.fiducial_id);
        }

        auto key =
            MakeFiducialWindowKey(
                window.drone_id,
                window.map_epoch,
                window.fiducial_id);

        auto it =
            active_fiducial_windows_.find(key);

        if (it != active_fiducial_windows_.end())
        {
            it->second.constrained_local_kfs.erase(local_kf_id);
            it->second.prior_local_kfs.erase(local_kf_id);
            it->second.good_prior_local_kfs.erase(local_kf_id);

            it->second.total_prior_count =
                it->second.prior_local_kfs.size();

            it->second.good_prior_count =
                it->second.good_prior_local_kfs.size();
        }

        if (removed_existing)
        {
            force_pose_graph_optimization_ = true;
            map_dirty_ = true;
            keyframes_dirty_ = true;
        }

        RCLCPP_WARN(
            get_logger(),
            "[PIPE0-FID-PRIOR-REJECT] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu global=%lu reason=too_far dist=%.3f dxy=%.3f "
            "reject_distance=%.3f source=%s removed_existing=%s world_kf_measured=%s",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id,
            global_kf_id,
            d3_fid,
            dxy_fid,
            fiducial_prior_reject_distance_m_,
            reason.c_str(),
            removed_existing ? "true" : "false",
            Tf2TranslationToString(T_world_kf_measured).c_str());

        return false;
    }

    orbslam3_multi::FiducialPoseConstraint constraint;

    constraint.drone_id =
        window.drone_id;

    constraint.map_epoch =
        window.map_epoch;

    constraint.global_kf_id =
        global_kf_id;

    constraint.local_kf_id =
        local_kf_id;

    constraint.fiducial_id =
        window.fiducial_id;

    constraint.measured_world_T_camera =
        Tf2ToEigenMatrix(
            T_world_kf_measured);

    constraint.weight =
        ComputeFiducialWindowPriorWeight(
            T_world_kf_measured,
            window);

    constraint.valid =
        true;

    // ============================================================
    // FASE 12R-B2:
    // Clasificar el prior fiducial según error contra la pose actual
    // del KF en el grafo global.
    // measured_world_T_camera = pose real/medida por fiducial.
    // current_world_T_kf = pose actual estimada por el servidor.
    // ============================================================

    Eigen::Matrix4d current_world_T_kf =
        Eigen::Matrix4d::Identity();

    std::string current_pose_source =
        "unknown";

    const bool has_current_world_pose =
        GetKeyFrameWorldPoseForLocalOptApply(
            global_kf_id,
            current_world_T_kf,
            current_pose_source);

    double fid_error_t_m =
        std::numeric_limits<double>::infinity();

    double fid_error_yaw_deg =
        std::numeric_limits<double>::infinity();

    double fid_error_rot_deg =
        std::numeric_limits<double>::infinity();

    if (has_current_world_pose &&
        current_world_T_kf.allFinite() &&
        constraint.measured_world_T_camera.allFinite())
    {
        const Eigen::Vector3d current_t =
            current_world_T_kf.block<3, 1>(0, 3);

        const Eigen::Vector3d measured_t =
            constraint.measured_world_T_camera.block<3, 1>(0, 3);

        fid_error_t_m =
            (current_t - measured_t).norm();

        const Eigen::Matrix4d measured_T_current =
            constraint.measured_world_T_camera.inverse() *
            current_world_T_kf;

        if (measured_T_current.allFinite())
        {
            fid_error_yaw_deg =
                std::abs(
                    NormalizeAngleDeg(
                        MatrixYawDeg(
                            measured_T_current)));

            fid_error_rot_deg =
                RotationAngleDeg(
                    measured_T_current.block<3, 3>(0, 0));
        }
    }

    std::string fiducial_classification =
        "FIDUCIAL_GLOBAL_DEBT";

    bool fiducial_hard_fixed =
        false;

    bool fiducial_global_debt =
        true;

    if (!has_current_world_pose)
    {
        if (local_opt_fiducial_no_current_pose_as_hard_anchor_)
        {
            fiducial_classification =
                "FIDUCIAL_INITIAL_HARD_ANCHOR";

            fiducial_hard_fixed =
                local_opt_constraint_hard_fix_fiducials_;

            fiducial_global_debt =
                false;
        }
        else
        {
            fiducial_classification =
                "FIDUCIAL_INITIAL_SOFT_PRIOR";

            fiducial_hard_fixed =
                false;

            fiducial_global_debt =
                false;
        }
    }
    else if (std::isfinite(fid_error_t_m) &&
            std::isfinite(fid_error_yaw_deg) &&
            std::isfinite(fid_error_rot_deg) &&
            fid_error_t_m <= local_opt_fiducial_hard_max_error_t_m_ &&
            fid_error_yaw_deg <= local_opt_fiducial_hard_max_yaw_deg_ &&
            fid_error_rot_deg <= local_opt_fiducial_hard_max_rot_deg_)
    {
        fiducial_classification =
            "FIDUCIAL_HARD_ANCHOR";

        fiducial_hard_fixed =
            local_opt_constraint_hard_fix_fiducials_;

        fiducial_global_debt =
            false;
    }
    else if (std::isfinite(fid_error_t_m) &&
            std::isfinite(fid_error_yaw_deg) &&
            std::isfinite(fid_error_rot_deg) &&
            fid_error_t_m <= local_opt_fiducial_soft_max_error_t_m_ &&
            fid_error_yaw_deg <= local_opt_fiducial_soft_max_yaw_deg_ &&
            fid_error_rot_deg <= local_opt_fiducial_soft_max_rot_deg_)
    {
        fiducial_classification =
            "FIDUCIAL_SOFT_PRIOR";

        fiducial_hard_fixed =
            false;

        fiducial_global_debt =
            false;
    }
    else
    {
        fiducial_classification =
            "FIDUCIAL_GLOBAL_DEBT";

        fiducial_hard_fixed =
            false;

        fiducial_global_debt =
            true;
    }

    RCLCPP_WARN(
        get_logger(),
        "[LOCAL-OPT-FID-CLASSIFY] drone_%u epoch=%lu fiducial_%u "
        "kf=%lu global=%lu classification=%s hard_fixed=%s global_debt=%s "
        "has_current_pose=%s current_pose_source=%s "
        "error_t=%.4f error_yaw=%.3f error_rot=%.3f "
        "hard_thr=(%.3f,%.3f,%.3f) soft_thr=(%.3f,%.3f,%.3f) "
        "measured_pos=(%.3f,%.3f,%.3f) current_pos=(%.3f,%.3f,%.3f) "
        "note=phase12r_b2_fiducial_prior_classified_by_pose_error",
        window.drone_id,
        window.map_epoch,
        window.fiducial_id,
        local_kf_id,
        global_kf_id,
        fiducial_classification.c_str(),
        fiducial_hard_fixed ? "true" : "false",
        fiducial_global_debt ? "true" : "false",
        has_current_world_pose ? "true" : "false",
        current_pose_source.c_str(),
        fid_error_t_m,
        fid_error_yaw_deg,
        fid_error_rot_deg,
        local_opt_fiducial_hard_max_error_t_m_,
        local_opt_fiducial_hard_max_yaw_deg_,
        local_opt_fiducial_hard_max_rot_deg_,
        local_opt_fiducial_soft_max_error_t_m_,
        local_opt_fiducial_soft_max_yaw_deg_,
        local_opt_fiducial_soft_max_rot_deg_,
        constraint.measured_world_T_camera(0, 3),
        constraint.measured_world_T_camera(1, 3),
        constraint.measured_world_T_camera(2, 3),
        current_world_T_kf(0, 3),
        current_world_T_kf(1, 3),
        current_world_T_kf(2, 3));

    // ============================================================
    // FASE 12R-B3:
    // Registrar siempre la restricción fiducial local del servidor,
    // incluso si MultiDroneSystem rechaza el prior por duplicado.
    // El grafo de restricciones del servidor es independiente.
    // ============================================================

    RememberLocalOptFiducialPriorKeyFrame(
        window.drone_id,
        window.map_epoch,
        local_kf_id,
        constraint.measured_world_T_camera,
        constraint.weight,
        fiducial_classification,
        fiducial_hard_fixed,
        fiducial_global_debt,
        fid_error_t_m,
        fid_error_yaw_deg,
        fid_error_rot_deg,
        has_current_world_pose,
        current_pose_source,
        now(),
        "fiducial_prior_seen_before_multisystem_store:" + reason);

    // ============================================================
    // FASE 12R-D2:
    // Si el KF está en FIDUCIAL_GLOBAL_DEBT, NO lo metemos al
    // MultiDroneSystem como prior fiducial normal. Es una medición de
    // error para futura optimización global, no una verdad fuerte.
    // ============================================================

    if (fiducial_global_debt &&
        !local_opt_fiducial_debt_add_to_multisystem_)
    {
        auto debt_key =
            MakeFiducialWindowKey(
                window.drone_id,
                window.map_epoch,
                window.fiducial_id);

        auto debt_it =
            active_fiducial_windows_.find(
                debt_key);

        bool debt_recorded =
            false;

        if (debt_it != active_fiducial_windows_.end())
        {
            const size_t debt_before =
                debt_it->second.debt_prior_local_kfs.size();

            if (debt_before <
                    static_cast<size_t>(
                        local_opt_fiducial_debt_max_new_per_window_) ||
                debt_it->second.debt_prior_local_kfs.count(local_kf_id) > 0)
            {
                debt_it->second.debt_prior_local_kfs.insert(
                    local_kf_id);

                debt_it->second.debt_prior_count =
                    debt_it->second.debt_prior_local_kfs.size();

                debt_recorded =
                    true;
            }
        }

        RCLCPP_WARN_THROTTLE(
            get_logger(),
            *get_clock(),
            1000,
            "[FID-DEBT-QUARANTINE] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu global=%lu class=%s error_t=%.4f error_yaw=%.3f error_rot=%.3f "
            "current_pose_source=%s recorded=%s debt_count=%zu "
            "add_to_multisystem=false force_legacy=false reason=%s "
            "note=phase12r_d2_debt_not_added_as_fiducial_prior",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id,
            global_kf_id,
            fiducial_classification.c_str(),
            fid_error_t_m,
            fid_error_yaw_deg,
            fid_error_rot_deg,
            current_pose_source.c_str(),
            debt_recorded ? "true" : "false",
            debt_it != active_fiducial_windows_.end()
                ? debt_it->second.debt_prior_count
                : 0,
            reason.c_str());

        return false;
    }

    const bool stored =
        multi_system_->AddFiducialPoseConstraint(
            constraint);

    if (!stored)
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-WINDOW-PRIOR-NOT-STORED] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu global=%lu reason=%s duplicate_or_invalid=true",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id,
            global_kf_id,
            reason.c_str());

        return false;
    }

    auto key =
        MakeFiducialWindowKey(
            window.drone_id,
            window.map_epoch,
            window.fiducial_id);

    auto it =
        active_fiducial_windows_.find(key);

    // FASE 12R-B2:
    // good_prior_local_kfs ya no significa "cerca del fiducial" solamente.
    // Para local optimization, un prior bueno es uno clasificado como ancla
    // dura por bajo error contra la pose real del fiducial.
    const bool is_good_fiducial_prior =
        fiducial_classification == "FIDUCIAL_HARD_ANCHOR" ||
        fiducial_classification == "FIDUCIAL_INITIAL_HARD_ANCHOR";

    if (it != active_fiducial_windows_.end())
    {
        it->second.constrained_local_kfs.insert(local_kf_id);

        if (fiducial_global_debt)
        {
            it->second.debt_prior_local_kfs.insert(local_kf_id);

            it->second.debt_prior_count =
                it->second.debt_prior_local_kfs.size();

            if (local_opt_fiducial_debt_count_as_ready_prior_)
            {
                it->second.prior_local_kfs.insert(local_kf_id);
            }
        }
        else
        {
            it->second.prior_local_kfs.insert(local_kf_id);
        }

        if (is_good_fiducial_prior)
        {
            it->second.good_prior_local_kfs.insert(local_kf_id);
        }

        it->second.total_prior_count =
            it->second.prior_local_kfs.size();

        it->second.good_prior_count =
            it->second.good_prior_local_kfs.size();
    }

    if (!fiducial_global_debt ||
        local_opt_fiducial_debt_force_legacy_optimization_)
    {
        force_pose_graph_optimization_ = true;
        last_loop_edge_time_ = now();
    }
    else
    {
        RCLCPP_WARN_THROTTLE(
            get_logger(),
            *get_clock(),
            1000,
            "[FID-DEBT-NO-FORCE-OPT] drone_%u epoch=%lu fiducial_%u "
            "kf=%lu global=%lu class=%s error_t=%.4f "
            "reason=debt_does_not_force_legacy_pose_graph "
            "note=phase12r_d2_prevent_legacy_optimizer_storm",
            window.drone_id,
            window.map_epoch,
            window.fiducial_id,
            local_kf_id,
            global_kf_id,
            fiducial_classification.c_str(),
            fid_error_t_m);
    }

    RCLCPP_WARN(
        get_logger(),
        "[PIPE0-FID-PRIOR-STORED] t=%.3f drone_%u epoch=%lu fiducial_%u "
        "kf=%lu global=%lu weight=%.3f source=%s "
        "dist=%.3f dxy=%.3f total_priors=%zu good_priors=%zu kf_stamp=%.3f "
        "fid_class=%s fid_error_t=%.4f fid_error_yaw=%.3f fid_error_rot=%.3f "
        "current_pose_source=%s hard_fixed=%s global_debt=%s "
        "world_kf_measured=%s local_kf=%s force_optimization=%s debt_count=%zu",
        now().seconds(),
        window.drone_id,
        window.map_epoch,
        window.fiducial_id,
        local_kf_id,
        global_kf_id,
        constraint.weight,
        reason.c_str(),
        d3_fid,
        dxy_fid,
        it != active_fiducial_windows_.end() ? it->second.total_prior_count : 0,
        it != active_fiducial_windows_.end() ? it->second.good_prior_count : 0,
        kf_stamp_s,
        fiducial_classification.c_str(),
        fid_error_t_m,
        fid_error_yaw_deg,
        fid_error_rot_deg,
        current_pose_source.c_str(),
        fiducial_hard_fixed ? "true" : "false",
        fiducial_global_debt ? "true" : "false",
        Tf2TranslationToString(T_world_kf_measured).c_str(),
        Tf2TranslationToString(T_local_kf).c_str(),
        (!fiducial_global_debt ||
        local_opt_fiducial_debt_force_legacy_optimization_) ? "true" : "false",
        it != active_fiducial_windows_.end()
            ? it->second.debt_prior_count
            : 0);

    return true;
}


void GlobalMapServer::RefreshExistingFiducialPriorsForWindow(
    ActiveFiducialWindow& window,
    DroneMapData& data,
    const std::string& reason)
{
    if (!window.active)
        return;

    if (window.constrained_local_kfs.empty())
        return;

    size_t refreshed = 0;
    size_t attempted = 0;

    std::vector<uint64_t> ids;
    ids.reserve(window.constrained_local_kfs.size());

    for (uint64_t local_kf_id : window.constrained_local_kfs)
    {
        ids.push_back(local_kf_id);
    }

    std::sort(ids.begin(), ids.end());

    size_t skipped_debt =
        0;

    for (uint64_t local_kf_id : ids)
    {
        if (!local_opt_fiducial_debt_refresh_enabled_ &&
            window.debt_prior_local_kfs.count(local_kf_id) > 0)
        {
            skipped_debt++;
            continue;
        }

        attempted++;

        const bool ok =
            TryCreateFiducialPriorForKeyFrame(
                window,
                data,
                local_kf_id,
                reason,
                true);

        if (ok)
            refreshed++;
    }

    RCLCPP_WARN(
        get_logger(),
        "[FID-WINDOW-PRIOR-REFRESH] drone_%u epoch=%lu fiducial_%u "
        "attempted=%zu refreshed=%zu skipped_debt=%zu debt_count=%zu reason=%s",
        window.drone_id,
        window.map_epoch,
        window.fiducial_id,
        attempted,
        refreshed,
        skipped_debt,
        window.debt_prior_count,
        reason.c_str());
}


bool GlobalMapServer::ShouldApplyLocalFiducialWarp(
    const ActiveFiducialWindow& window,
    const std::string& reason) const
{
    if (!enable_local_fiducial_cache_warp_)
        return false;

    if (!window.active)
        return false;

    /*
     * Regla principal:
     * El warp local solo se permite como ayuda inicial,
     * antes de que exista una solución OPT9.
     *
     * Cuando optimized_kf_poses_ ya no está vacío, significa que
     * el pose graph ya ha producido una solución. A partir de ahí,
     * el warp local puede deshacer visualmente la optimización.
     */
    const bool has_previous_different_fiducial =
        HasSeenDifferentFiducialInEpoch(
            window.drone_id,
            window.map_epoch,
            window.fiducial_id);

    if (!optimized_kf_poses_.empty() &&
        !has_previous_different_fiducial)
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-LOCAL-WARP-SKIP] fiducial_%u reason=%s "
            "because optimized_kf_poses already exists (%zu) "
            "and no previous different fiducial was seen",
            window.fiducial_id,
            reason.c_str(),
            optimized_kf_poses_.size());

        return false;
    }

    /*
     * No queremos hacer warp en refrescos de ventana.
     * Solo tiene sentido cuando se acaba de crear un prior real.
     */
    if (reason == "after_window_update" ||
        reason == "best_observation_refresh" ||
        reason == "refresh_existing")
    {
        RCLCPP_WARN(
            get_logger(),
            "[FID-LOCAL-WARP-SKIP] fiducial_%u reason=%s "
            "because this is only a refresh/update",
            window.fiducial_id,
            reason.c_str());

        return false;
    }

    return true;
}


void GlobalMapServer::TryAssociateKeyFrameToActiveFiducialWindows(
    uint32_t drone_id,
    uint64_t map_epoch,
    uint64_t local_kf_id)
{
    auto data_it =
        drone_maps_.find(drone_id);

    if (data_it == drone_maps_.end())
        return;

    DroneMapData& data =
        data_it->second;

    for (auto& [key, window] : active_fiducial_windows_)
    {
        if (!window.active)
            continue;

        if (window.drone_id != drone_id)
            continue;

        if (window.map_epoch != map_epoch)
            continue;

        if (local_kf_id <= window.max_local_kf_id_at_enter)
            continue;

        const bool created =
            TryCreateFiducialPriorForKeyFrame(
                window,
                data,
                local_kf_id,
                "new_kf_callback");

        if (created &&
            ShouldApplyLocalFiducialWarp(window, "new_kf_callback"))
        {
            ApplyLocalFiducialCacheWarp(
                drone_id,
                data,
                window,
                window.T_world_camera_last,
                window.T_local_camera_last,
                window.min_distance_to_fiducial,
                "new_kf_callback");
        }
    }
}


double GlobalMapServer::ComputeFiducialWindowPriorWeight(
    const tf2::Transform& T_world_kf_measured,
    const ActiveFiducialWindow& window) const
{
    const tf2::Vector3 kf_pos =
        T_world_kf_measured.getOrigin();

    const tf2::Vector3 fid_pos =
        window.T_world_fiducial.getOrigin();

    const double dx =
        kf_pos.x() - fid_pos.x();

    const double dy =
        kf_pos.y() - fid_pos.y();

    const double dz =
        kf_pos.z() - fid_pos.z();

    const double d3 =
        std::sqrt(dx * dx + dy * dy + dz * dz);

    // Priors simulados: si un KF está realmente en el fiducial,
    // debe pesar bastante. Los lejanos ya se rechazan antes.
    if (d3 <= 0.75)
        return 120.0;

    if (d3 <= 1.5)
        return 90.0;

    if (d3 <= 2.25)
        return 60.0;

    return 35.0;
}


void GlobalMapServer::TryCreateBackfillPriorsForWindow(
    ActiveFiducialWindow& window,
    DroneMapData& data)
{
    if (fiducial_window_backfill_kfs_ <= 0)
        return;

    std::vector<uint64_t> ids;

    for (const auto& [local_kf_id, kf] : data.keyframes)
    {
        if (!kf.is_bad)
            ids.push_back(local_kf_id);
    }

    std::sort(ids.begin(), ids.end(), std::greater<uint64_t>());

    int created = 0;

    for (uint64_t local_kf_id : ids)
    {
        if (created >= fiducial_window_backfill_kfs_)
            break;

        if (TryCreateFiducialPriorForKeyFrame(
                window,
                data,
                local_kf_id,
                "window_backfill"))
        {
            created++;
        }
    }

    RCLCPP_WARN(
        get_logger(),
        "[FID-WINDOW-BACKFILL] drone_%u epoch=%lu fiducial_%u created=%d requested=%d",
        window.drone_id,
        window.map_epoch,
        window.fiducial_id,
        created,
        fiducial_window_backfill_kfs_);
}


void GlobalMapServer::EigenMatrixToTf2(
    const Eigen::Matrix4d& T,
    tf2::Transform& out) const
{
    Eigen::Matrix3d R =
        T.block<3, 3>(0, 0);

    Eigen::Quaterniond q_eigen(R);
    q_eigen.normalize();

    tf2::Quaternion q(
        q_eigen.x(),
        q_eigen.y(),
        q_eigen.z(),
        q_eigen.w());

    q.normalize();

    out.setOrigin(
        tf2::Vector3(
            T(0, 3),
            T(1, 3),
            T(2, 3)));

    out.setRotation(q);
}


orbslam3_msgs::msg::CorrectedKeyFrameArray
GlobalMapServer::BuildCorrectedKeyFrameArrayForDrone(
    uint32_t drone_id,
    const DroneMapData& data)
{
    orbslam3_msgs::msg::CorrectedKeyFrameArray msg;

    msg.header.stamp =
        now();

    msg.header.frame_id =
        world_frame_;

    msg.drone_id =
        drone_id;

    msg.drone_name =
        namespace_base_ + "_" + std::to_string(drone_id);

    msg.world_frame =
        world_frame_;

    msg.local_map_frame =
        msg.drone_name + "_orb_map";

    if (!data.has_correction)
    {
        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            1000,
            "[POSE4B-KF-BUILD-SKIP] drone_%u reason=no_map_correction",
            drone_id);

        return msg;
    }

    if (multi_system_)
    {
        orbslam3_multi::MapAnchor anchor_info;

        if (multi_system_->GetMapAnchorInfo(
                drone_id,
                data.current_map_epoch,
                anchor_info))
        {
            if (anchor_info.source ==
                    orbslam3_multi::AnchorSource::LOOP_OR_PROPAGATED &&
                anchor_info.maturity !=
                    orbslam3_multi::AnchorMaturity::CONFIRMED)
            {
                RCLCPP_WARN_THROTTLE(
                    get_logger(),
                    *get_clock(),
                    1000,
                    "[POSE4B-KF-BUILD-SKIP] drone_%u epoch=%lu "
                    "reason=loop_anchor_not_confirmed maturity=PROVISIONAL "
                    "action=publish_empty_corrected_keyframes",
                    drone_id,
                    data.current_map_epoch);

                return msg;
            }
        }
    }

    tf2::Transform tf_world_local =
        TransformMsgToTf2(data.world_T_local);

    Eigen::Matrix4d world_T_local =
        Tf2ToEigenMatrix(tf_world_local);

    size_t used_optimized = 0;
    size_t used_rigid = 0;
    size_t skipped_bad = 0;
    size_t skipped_not_finite = 0;

    std::vector<uint64_t> local_kf_ids;
    local_kf_ids.reserve(data.keyframes.size());

    for (const auto& [local_kf_id, kf_msg] : data.keyframes)
    {
        if (kf_msg.is_bad)
            continue;

        local_kf_ids.push_back(local_kf_id);
    }

    std::sort(
        local_kf_ids.begin(),
        local_kf_ids.end(),
        std::greater<uint64_t>());

    for (uint64_t local_kf_id : local_kf_ids)
    {
        if (msg.keyframes.size() >=
            static_cast<size_t>(corrected_keyframes_max_per_drone_))
        {
            break;
        }

        auto kf_it =
            data.keyframes.find(local_kf_id);

        if (kf_it == data.keyframes.end())
            continue;

        const auto& kf_msg =
            kf_it->second;

        if (kf_msg.is_bad)
        {
            skipped_bad++;
            continue;
        }

        const uint64_t global_kf_id =
            MakeGlobalId(
                drone_id,
                data.current_map_epoch,
                local_kf_id);

        tf2::Transform tf_local_kf =
            PoseMsgToTf2(kf_msg.pose);

        if (!IsFiniteTransform(tf_local_kf))
        {
            skipped_not_finite++;
            continue;
        }

        Eigen::Matrix4d local_T_kf =
            Tf2ToEigenMatrix(tf_local_kf);

        Eigen::Matrix4d world_T_kf_original =
            world_T_local *
            local_T_kf;

        Eigen::Matrix4d world_T_kf_corrected =
            world_T_kf_original;

        auto opt_it =
            optimized_kf_poses_.find(global_kf_id);

        if (opt_it != optimized_kf_poses_.end() &&
            opt_it->second.allFinite())
        {
            world_T_kf_corrected =
                opt_it->second;

            used_optimized++;
        }
        else
        {
            if (!corrected_keyframes_publish_rigid_fallback_)
                continue;

            used_rigid++;
        }

        if (!world_T_kf_original.allFinite() ||
            !world_T_kf_corrected.allFinite())
        {
            skipped_not_finite++;
            continue;
        }

        orbslam3_msgs::msg::CorrectedKeyFrame out_kf;

        out_kf.keyframe_id =
            local_kf_id;

        out_kf.original_local_pose =
            kf_msg.pose;

        out_kf.original_global_pose =
            MatrixToPoseMsg(world_T_kf_original);

        out_kf.corrected_global_pose =
            MatrixToPoseMsg(world_T_kf_corrected);

        msg.keyframes.push_back(out_kf);
    }

    RCLCPP_INFO_THROTTLE(
        get_logger(),
        *get_clock(),
        500,
        "[POSE4B-KF-BUILD] drone_%u epoch=%lu output_kfs=%zu "
        "used_optimized=%zu used_rigid=%zu skipped_bad=%zu skipped_not_finite=%zu "
        "optimized_kf_poses=%zu has_correction=%s absolute=%s",
        drone_id,
        data.current_map_epoch,
        msg.keyframes.size(),
        used_optimized,
        used_rigid,
        skipped_bad,
        skipped_not_finite,
        optimized_kf_poses_.size(),
        data.has_correction ? "true" : "false",
        data.has_absolute_correction ? "true" : "false");

    return msg;
}


void GlobalMapServer::PublishCorrectedKeyFrames()
{
    if (!publish_corrected_keyframes_)
        return;

    for (const auto& [drone_id, data] : drone_maps_)
    {
        auto pub_it =
            corrected_keyframes_pubs_.find(drone_id);

        if (pub_it == corrected_keyframes_pubs_.end() ||
            !pub_it->second)
        {
            RCLCPP_WARN_THROTTLE(
                get_logger(),
                *get_clock(),
                1000,
                "[POSE4B-KF-PUB-SKIP] drone_%u reason=no_publisher",
                drone_id);

            continue;
        }

        orbslam3_msgs::msg::CorrectedKeyFrameArray msg =
            BuildCorrectedKeyFrameArrayForDrone(
                drone_id,
                data);

        pub_it->second->publish(msg);

        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            500,
            "[POSE4B-KF-PUB] drone_%u keyframes=%zu topic=/dron_%u/corrected_keyframes",
            drone_id,
            msg.keyframes.size(),
            drone_id);
    }
}


void GlobalMapServer::ClearTestedPairsForDroneIfRequested(
    uint32_t drone_id)
{
    if (!intra_drone_loop_assist_clear_tested_pairs_)
        return;

    size_t erased = 0;

    for (auto it = tested_pairs_.begin();
         it != tested_pairs_.end(); )
    {
        const uint32_t a_drone =
            ExtractDroneId(it->a);

        const uint32_t b_drone =
            ExtractDroneId(it->b);

        if (a_drone == drone_id && b_drone == drone_id)
        {
            it = tested_pairs_.erase(it);
            erased++;
        }
        else
        {
            ++it;
        }
    }

    if (erased > 0)
    {
        RCLCPP_WARN(
            get_logger(),
            "[INTRA-LOOP-ASSIST-CLEAR-TESTED] drone_%u erased=%zu",
            drone_id,
            erased);
    }
}

size_t GlobalMapServer::RequeueIntraDroneLoopCandidatesForDrone(
    uint32_t drone_id,
    const DroneMapData& data)
{
    if (data.keyframes.size() < 2)
        return 0;

    if (intra_drone_loop_assist_only_anchored_ &&
        !data.has_correction)
    {
        RCLCPP_INFO_THROTTLE(
            get_logger(),
            *get_clock(),
            1000,
            "[INTRA-LOOP-ASSIST-SKIP] drone_%u reason=not_anchored",
            drone_id);

        return 0;
    }

    std::vector<uint64_t> local_ids;
    local_ids.reserve(data.keyframes.size());

    for (const auto& [local_id, kf_msg] : data.keyframes)
    {
        if (kf_msg.is_bad)
            continue;

        local_ids.push_back(local_id);
    }

    if (local_ids.size() < 2)
        return 0;

    std::sort(local_ids.begin(), local_ids.end());

    std::vector<uint64_t> to_requeue;

    // 1) KFs recientes.
    const size_t recent_count =
        std::min<size_t>(
            local_ids.size(),
            static_cast<size_t>(intra_drone_loop_assist_recent_kfs_));

    for (size_t i = 0; i < recent_count; ++i)
    {
        const uint64_t local_id =
            local_ids[local_ids.size() - 1 - i];

        to_requeue.push_back(local_id);
    }

    // 2) KFs históricos espaciados.
    size_t added_history = 0;

    for (size_t idx = 0;
         idx < local_ids.size() &&
         added_history < static_cast<size_t>(intra_drone_loop_assist_history_kfs_);
         idx += static_cast<size_t>(intra_drone_loop_assist_history_stride_))
    {
        to_requeue.push_back(local_ids[idx]);
        added_history++;
    }

    // Deduplicar local ids.
    std::sort(to_requeue.begin(), to_requeue.end());
    to_requeue.erase(
        std::unique(to_requeue.begin(), to_requeue.end()),
        to_requeue.end());

    size_t requeued = 0;

    for (uint64_t local_id : to_requeue)
    {
        if (requeued >=
            static_cast<size_t>(intra_drone_loop_assist_max_requeue_per_drone_))
        {
            break;
        }

        const uint64_t global_kf_id =
            MakeGlobalKeyFrameId(
                drone_id,
                data.current_map_epoch,
                local_id);

        orbslam3_multi::ImportedKeyFrame kf =
            multi_system_->GetAtlas()->GetKeyFrame(global_kf_id);

        if (kf.global_id == 0 || kf.is_bad || kf.bow_word_ids.empty())
            continue;

        if (pending_bow_query_kfs_set_.find(global_kf_id) !=
            pending_bow_query_kfs_set_.end())
        {
            continue;
        }

        pending_bow_query_kfs_.push_back(global_kf_id);
        pending_bow_query_kfs_set_.insert(global_kf_id);

        requeued++;
    }

    RCLCPP_INFO(
        get_logger(),
        "[INTRA-LOOP-ASSIST-REQUEUE] drone_%u epoch=%lu local_kfs=%zu "
        "requested_recent=%d requested_history=%d stride=%d requeued=%zu "
        "pending=%zu tested=%zu anchored=%s",
        drone_id,
        data.current_map_epoch,
        local_ids.size(),
        intra_drone_loop_assist_recent_kfs_,
        intra_drone_loop_assist_history_kfs_,
        intra_drone_loop_assist_history_stride_,
        requeued,
        pending_bow_query_kfs_.size(),
        tested_pairs_.size(),
        data.has_correction ? "true" : "false");

    return requeued;
}


void GlobalMapServer::IntraDroneLoopAssistTimerCallback()
{
    if (!enable_intra_drone_loop_assist_)
        return;

    if (!enable_intra_drone_loop_detection_)
        return;

    if (!multi_system_)
        return;

    size_t total_requeued = 0;

    for (auto& [drone_id, data] : drone_maps_)
    {
        ClearTestedPairsForDroneIfRequested(drone_id);

        total_requeued +=
            RequeueIntraDroneLoopCandidatesForDrone(
                drone_id,
                data);
    }

    if (total_requeued > 0)
    {
        RCLCPP_WARN_THROTTLE(
            get_logger(),
            *get_clock(),
            1000,
            "[INTRA-LOOP-ASSIST-TICK] total_requeued=%zu pending=%zu bow_queue=%zu tested=%zu",
            total_requeued,
            pending_bow_query_kfs_.size(),
            bow_candidate_queue_.size(),
            tested_pairs_.size());
    }
}


bool GlobalMapServer::EnqueueDirectLandmarkAssociationPair(
    uint64_t query_global_kf_id,
    uint64_t candidate_global_kf_id,
    const std::string& reason)
{
    if (query_global_kf_id == 0 ||
        candidate_global_kf_id == 0 ||
        query_global_kf_id == candidate_global_kf_id)
    {
        return false;
    }

    const uint32_t q_drone =
        ExtractDroneId(query_global_kf_id);

    const uint32_t c_drone =
        ExtractDroneId(candidate_global_kf_id);

    const uint64_t q_epoch =
        ExtractMapEpoch(query_global_kf_id);

    const uint64_t c_epoch =
        ExtractMapEpoch(candidate_global_kf_id);

    // Fase 5D-B solo intra mismo dron/mismo epoch.
    if (q_drone != c_drone || q_epoch != c_epoch)
        return false;

    KeyFramePairKey pair;
    pair.a = std::min(query_global_kf_id, candidate_global_kf_id);
    pair.b = std::max(query_global_kf_id, candidate_global_kf_id);

    if (direct_assoc_processed_pairs_.find(pair) !=
        direct_assoc_processed_pairs_.end())
    {
        return false;
    }

    if (direct_assoc_queued_pairs_.find(pair) !=
        direct_assoc_queued_pairs_.end())
    {
        return false;
    }

    DirectLandmarkAssociationJob job;
    job.query_global_kf_id = query_global_kf_id;
    job.candidate_global_kf_id = candidate_global_kf_id;
    job.reason = reason;

    direct_assoc_queue_.push_back(job);
    direct_assoc_queued_pairs_.insert(pair);

    while (static_cast<int>(direct_assoc_queue_.size()) >
           direct_assoc_max_queue_size_)
    {
        const auto old =
            direct_assoc_queue_.front();

        direct_assoc_queue_.pop_front();

        KeyFramePairKey old_pair;
        old_pair.a = std::min(
            old.query_global_kf_id,
            old.candidate_global_kf_id);
        old_pair.b = std::max(
            old.query_global_kf_id,
            old.candidate_global_kf_id);

        direct_assoc_queued_pairs_.erase(old_pair);
    }

    return true;
}


void GlobalMapServer::QueueDirectLandmarkAssociationsForDrone(
    uint32_t drone_id,
    const DroneMapData& data)
{
    if (data.keyframes.size() < 2)
        return;

    std::vector<uint64_t> local_ids;
    local_ids.reserve(data.keyframes.size());

    for (const auto& [local_id, kf_msg] : data.keyframes)
    {
        if (kf_msg.is_bad)
            continue;

        local_ids.push_back(local_id);
    }

    if (local_ids.size() < 2)
        return;

    std::sort(local_ids.begin(), local_ids.end());

    size_t queued = 0;

    // ------------------------------------------------------------
    // 1) Consecutivos: kf_i contra kf_{i-1}
    // ------------------------------------------------------------
    if (direct_assoc_use_consecutive_kfs_)
    {
        const size_t recent_count =
            std::min<size_t>(
                local_ids.size(),
                static_cast<size_t>(direct_assoc_recent_kfs_));

        const size_t start =
            local_ids.size() - recent_count;

        for (size_t i = std::max<size_t>(start, 1);
             i < local_ids.size();
             ++i)
        {
            const uint64_t q_local =
                local_ids[i];

            const uint64_t c_local =
                local_ids[i - 1];

            const uint64_t q_global =
                MakeGlobalId(
                    drone_id,
                    data.current_map_epoch,
                    q_local);

            const uint64_t c_global =
                MakeGlobalId(
                    drone_id,
                    data.current_map_epoch,
                    c_local);

            if (EnqueueDirectLandmarkAssociationPair(
                    q_global,
                    c_global,
                    "consecutive"))
            {
                queued++;
            }
        }
    }

    // ------------------------------------------------------------
    // 2) Revisitas locales:
    //    KFs recientes contra KFs históricos con posición local cercana.
    // ------------------------------------------------------------
    if (direct_assoc_use_revisit_kfs_)
    {
        const size_t recent_count =
            std::min<size_t>(
                local_ids.size(),
                static_cast<size_t>(direct_assoc_recent_kfs_));

        const size_t recent_start =
            local_ids.size() - recent_count;

        size_t history_checked = 0;

        for (size_t ri = recent_start;
             ri < local_ids.size();
             ++ri)
        {
            const uint64_t q_local =
                local_ids[ri];

            auto q_it =
                data.keyframes.find(q_local);

            if (q_it == data.keyframes.end())
                continue;

            tf2::Transform q_tf =
                PoseMsgToTf2(q_it->second.pose);

            const tf2::Vector3 q_pos =
                q_tf.getOrigin();

            for (size_t hi = 0;
                 hi < recent_start &&
                 history_checked < static_cast<size_t>(direct_assoc_history_kfs_);
                 hi += static_cast<size_t>(direct_assoc_history_stride_))
            {
                history_checked++;

                const uint64_t c_local =
                    local_ids[hi];

                const uint64_t gap =
                    q_local > c_local
                        ? q_local - c_local
                        : c_local - q_local;

                if (gap < direct_assoc_min_revisit_kf_gap_)
                    continue;

                auto c_it =
                    data.keyframes.find(c_local);

                if (c_it == data.keyframes.end())
                    continue;

                tf2::Transform c_tf =
                    PoseMsgToTf2(c_it->second.pose);

                const tf2::Vector3 c_pos =
                    c_tf.getOrigin();

                const double dx =
                    q_pos.x() - c_pos.x();

                const double dy =
                    q_pos.y() - c_pos.y();

                const double dz =
                    q_pos.z() - c_pos.z();

                const double local_dist =
                    std::sqrt(dx * dx + dy * dy + dz * dz);

                if (local_dist > direct_assoc_revisit_local_distance_m_)
                    continue;

                const uint64_t q_global =
                    MakeGlobalId(
                        drone_id,
                        data.current_map_epoch,
                        q_local);

                const uint64_t c_global =
                    MakeGlobalId(
                        drone_id,
                        data.current_map_epoch,
                        c_local);

                if (EnqueueDirectLandmarkAssociationPair(
                        q_global,
                        c_global,
                        "local_revisit"))
                {
                    queued++;
                }
            }
        }
    }

    if (queued > 0)
    {
        RCLCPP_INFO(
            get_logger(),
            "[DIRECT5D-QUEUE] drone_%u epoch=%lu local_kfs=%zu queued=%zu "
            "queue=%zu processed=%zu",
            drone_id,
            data.current_map_epoch,
            local_ids.size(),
            queued,
            direct_assoc_queue_.size(),
            direct_assoc_processed_pairs_.size());
    }
}



void GlobalMapServer::DirectLandmarkAssociationTimerCallback()
{
    if (!enable_direct_landmark_association_)
        return;

    if (!multi_system_)
        return;

    for (const auto& [drone_id, data] : drone_maps_)
    {
        QueueDirectLandmarkAssociationsForDrone(
            drone_id,
            data);
    }

    ProcessDirectLandmarkAssociationQueue();
}



void GlobalMapServer::ProcessDirectLandmarkAssociationQueue()
{
    if (!enable_direct_landmark_association_)
        return;

    size_t processed = 0;
    size_t stored = 0;
    size_t rejected = 0;

    while (!direct_assoc_queue_.empty() &&
           processed < static_cast<size_t>(direct_assoc_max_jobs_per_tick_))
    {
        DirectLandmarkAssociationJob job =
            direct_assoc_queue_.front();

        direct_assoc_queue_.pop_front();

        KeyFramePairKey pair;
        pair.a = std::min(
            job.query_global_kf_id,
            job.candidate_global_kf_id);
        pair.b = std::max(
            job.query_global_kf_id,
            job.candidate_global_kf_id);

        direct_assoc_queued_pairs_.erase(pair);

        const bool ok =
            ProcessDirectLandmarkAssociationJob(job);

        direct_assoc_processed_pairs_.insert(pair);

        if (ok)
            stored++;
        else
            rejected++;

        processed++;
    }

    if (processed > 0)
    {
        RCLCPP_INFO(
            get_logger(),
            "[DIRECT5D-PROCESS] processed=%zu stored=%zu rejected=%zu "
            "remaining=%zu processed_pairs=%zu",
            processed,
            stored,
            rejected,
            direct_assoc_queue_.size(),
            direct_assoc_processed_pairs_.size());
    }
}



bool GlobalMapServer::ProcessDirectLandmarkAssociationJob(
    const DirectLandmarkAssociationJob& job)
{
    if (!multi_system_)
        return false;

    auto atlas =
        multi_system_->GetAtlas();

    if (!atlas)
        return false;

    orbslam3_multi::ImportedKeyFrame q_kf =
        atlas->GetKeyFrame(job.query_global_kf_id);

    orbslam3_multi::ImportedKeyFrame c_kf =
        atlas->GetKeyFrame(job.candidate_global_kf_id);

    if (q_kf.global_id == 0 ||
        c_kf.global_id == 0 ||
        q_kf.is_bad ||
        c_kf.is_bad)
    {
        return false;
    }

    if (q_kf.drone_id != c_kf.drone_id ||
        q_kf.map_epoch != c_kf.map_epoch)
    {
        return false;
    }

    std::vector<orbslam3_multi::FeatureMatch> raw_matches;

    const int raw_count =
        SearchMatchesByBoW(
            job.query_global_kf_id,
            job.candidate_global_kf_id,
            raw_matches);

    orbslam3_multi::DirectLandmarkAssociation assoc;

    assoc.query_kf_id =
        job.query_global_kf_id;

    assoc.candidate_kf_id =
        job.candidate_global_kf_id;

    assoc.drone_id =
        q_kf.drone_id;

    assoc.map_epoch =
        q_kf.map_epoch;

    assoc.query_local_kf_id =
        q_kf.local_id;

    assoc.candidate_local_kf_id =
        c_kf.local_id;

    assoc.reason =
        job.reason;

    assoc.candidate_matches =
        raw_matches.size();

    if (raw_count < direct_assoc_min_raw_matches_)
    {
        RCLCPP_INFO(
            get_logger(),
            "[DIRECT5D-REJECT] reason=not_enough_raw_matches "
            "drone_%u epoch=%lu q_kf=%lu c_kf=%lu raw=%d min=%d job_reason=%s",
            q_kf.drone_id,
            q_kf.map_epoch,
            q_kf.local_id,
            c_kf.local_id,
            raw_count,
            direct_assoc_min_raw_matches_,
            job.reason.c_str());

        return false;
    }

    double dist_sum = 0.0;
    size_t dist_count = 0;

    for (const auto& m : raw_matches)
    {
        if (m.query_mappoint_id == 0 ||
            m.candidate_mappoint_id == 0)
        {
            assoc.rejected_zero_mp++;
            continue;
        }

        if (m.query_mappoint_id == m.candidate_mappoint_id)
        {
            assoc.rejected_same_mp++;
            continue;
        }

        if (m.distance > direct_assoc_max_descriptor_distance_)
        {
            assoc.rejected_descriptor++;
            continue;
        }

        orbslam3_multi::ImportedMapPoint q_mp =
            atlas->GetMapPoint(m.query_mappoint_id);

        orbslam3_multi::ImportedMapPoint c_mp =
            atlas->GetMapPoint(m.candidate_mappoint_id);

        if (q_mp.global_id == 0 ||
            c_mp.global_id == 0)
        {
            assoc.rejected_missing_mp++;
            continue;
        }

        if (q_mp.is_bad || c_mp.is_bad)
        {
            assoc.rejected_bad_mp++;
            continue;
        }

        if (q_mp.drone_id != c_mp.drone_id ||
            q_mp.map_epoch != c_mp.map_epoch)
        {
            assoc.rejected_missing_mp++;
            continue;
        }

        const double local_dist =
            (q_mp.position - c_mp.position).norm();

        if (!std::isfinite(local_dist) ||
            local_dist > direct_assoc_max_local_mp_distance_m_)
        {
            assoc.rejected_distance++;

            static size_t fusion6_direct_reject_sample_logs = 0;

            if (fusion6_log_direct_pair_samples_ &&
                fusion6_direct_reject_sample_logs <
                    static_cast<size_t>(fusion6_max_direct_pair_sample_logs_))
            {
                RCLCPP_INFO(
                    get_logger(),
                    "[FUSION6-DIRECT-REJECT] reason=%s reject=distance "
                    "q_kf=%lu c_kf=%lu q_mp=%lu c_mp=%lu "
                    "dist_m=%.4f max_dist=%.4f desc=%d",
                    job.reason.c_str(),
                    job.query_global_kf_id,
                    job.candidate_global_kf_id,
                    m.query_mappoint_id,
                    m.candidate_mappoint_id,
                    local_dist,
                    direct_assoc_max_local_mp_distance_m_,
                    m.distance);
                fusion6_direct_reject_sample_logs++;
            }

            continue;
        }

        assoc.matches.push_back(m);

        static size_t fusion6_direct_sample_logs = 0;

        if (fusion6_log_direct_pair_samples_ &&
            fusion6_direct_sample_logs <
                static_cast<size_t>(fusion6_max_direct_pair_sample_logs_))
        {
            RCLCPP_INFO(
                get_logger(),
                "[FUSION6-DIRECT-ACCEPT] reason=%s "
                "q_kf=%lu c_kf=%lu q_mp=%lu c_mp=%lu "
                "dist_m=%.4f desc=%d",
                job.reason.c_str(),
                job.query_global_kf_id,
                job.candidate_global_kf_id,
                m.query_mappoint_id,
                m.candidate_mappoint_id,
                local_dist,
                m.distance);

            fusion6_direct_sample_logs++;
        }

        assoc.accepted_matches++;

        dist_sum += local_dist;
        dist_count++;

        if (local_dist > assoc.max_distance_m)
            assoc.max_distance_m = local_dist;
    }

    if (dist_count > 0)
    {
        assoc.mean_distance_m =
            dist_sum /
            static_cast<double>(dist_count);
    }

    if (assoc.accepted_matches <
        static_cast<size_t>(direct_assoc_min_accepted_matches_))
    {
        RCLCPP_INFO(
            get_logger(),
            "[DIRECT5D-REJECT] reason=not_enough_accepted_matches "
            "drone_%u epoch=%lu q_kf=%lu c_kf=%lu raw=%zu accepted=%zu min=%d "
            "zero=%zu same=%zu missing=%zu bad=%zu dist=%zu desc=%zu job_reason=%s",
            q_kf.drone_id,
            q_kf.map_epoch,
            q_kf.local_id,
            c_kf.local_id,
            raw_matches.size(),
            assoc.accepted_matches,
            direct_assoc_min_accepted_matches_,
            assoc.rejected_zero_mp,
            assoc.rejected_same_mp,
            assoc.rejected_missing_mp,
            assoc.rejected_bad_mp,
            assoc.rejected_distance,
            assoc.rejected_descriptor,
            job.reason.c_str());

        return false;
    }

    assoc.valid =
        true;

    const bool stored =
        multi_system_->AddDirectLandmarkAssociation(
            assoc);

    RCLCPP_WARN(
        get_logger(),
        "[DIRECT5D-ACCEPT] stored=%s drone_%u epoch=%lu q_kf=%lu c_kf=%lu "
        "reason=%s raw=%zu accepted=%zu mean_dist=%.4f max_dist=%.4f "
        "zero=%zu same=%zu missing=%zu bad=%zu dist_rej=%zu desc_rej=%zu",
        stored ? "true" : "false",
        q_kf.drone_id,
        q_kf.map_epoch,
        q_kf.local_id,
        c_kf.local_id,
        job.reason.c_str(),
        raw_matches.size(),
        assoc.accepted_matches,
        assoc.mean_distance_m,
        assoc.max_distance_m,
        assoc.rejected_zero_mp,
        assoc.rejected_same_mp,
        assoc.rejected_missing_mp,
        assoc.rejected_bad_mp,
        assoc.rejected_distance,
        assoc.rejected_descriptor);

    return stored;
}



int main(int argc, char** argv)
{
    rclcpp::init(argc, argv);
    auto node = std::make_shared<GlobalMapServer>();
    rclcpp::spin(node);
    rclcpp::shutdown();
    return 0;
}

